import { Controller, Get, Param, Query, UseFilters } from '@nestjs/common';
import {
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiQuery,
  ApiTags,
} from '@nestjs/swagger';
import { BatchTagsResponseDto } from '@/commit/dto/batch-tags-response.dto';
import { RepoReferencesResponseDto } from '@/commit/dto/branches-by-commit-response.dto';
import { CommitTagsBatchQueryDto } from '@/commit/dto/commit-tags-batch-query.dto';
import { CommitTagsQueryDto } from '@/commit/dto/commit-tags-query.dto';
import { CommitsByPRResponseDto } from '@/commit/dto/commits-by-pr-response.dto';
import { CommitsByWorkItemResponseDto } from '@/commit/dto/commits-by-work-item-response.dto';
import { CommitService } from '@/commit/service/commit.service';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';

@ApiTags('commits')
@Controller('commits')
@UseFilters(MesGenericErrorFilter)
export class CommitController {
  public constructor(private readonly commitService: CommitService) {}

  @Get('/workitems/:workItemId')
  @ApiOperation({ summary: 'Get commits linked to a work item' })
  @ApiParam({ description: 'Work item ID', name: 'workItemId', type: 'number' })
  @ApiQuery({
    description: 'Azure DevOps project name',
    name: 'project',
    required: false,
  })
  @ApiOkResponse({
    description: 'Commits linked to work item returned',
    type: CommitsByWorkItemResponseDto,
  })
  public async getCommitsByWorkItem(
    @Param('workItemId') workItemId: string,
    @Query('project') project?: string,
  ): Promise<CommitsByWorkItemResponseDto> {
    const workItemIdNumber = Number(workItemId);

    const data = await this.commitService.getCommitsByWorkitem(
      project ?? '',
      workItemIdNumber,
    );

    return CommitsByWorkItemResponseDto.from(
      data.workItemId,
      data.project,
      data.commits,
    );
  }

  @Get('/branches')
  @ApiOperation({ summary: 'Get repository branches and tags' })
  @ApiQuery({
    description: 'Azure DevOps project name',
    name: 'project',
    required: true,
  })
  @ApiQuery({
    description: 'Repository name',
    name: 'repositoryName',
    required: true,
  })
  @ApiOkResponse({
    description: 'Repository branches and tags returned',
    type: RepoReferencesResponseDto,
  })
  public async getRepoBranchesAndTags(
    @Query('project') project: string,
    @Query('repositoryName') repositoryName: string,
  ): Promise<RepoReferencesResponseDto> {
    return this.commitService.getRepoBranchesAndTags(project, repositoryName);
  }

  @Get('/pullrequests/:prId')
  @ApiOperation({ summary: 'Get commits linked to a pull request' })
  @ApiParam({ description: 'Pull request ID', name: 'prId', type: 'number' })
  @ApiQuery({
    description: 'Azure DevOps project name',
    name: 'project',
    required: false,
  })
  @ApiOkResponse({
    description: 'Commits linked to pull request returned',
    type: CommitsByPRResponseDto,
  })
  public async getCommitsByPR(
    @Param('prId') prId: string,
    @Query('project') project?: string,
  ): Promise<CommitsByPRResponseDto> {
    const prIdNumber = Number(prId);

    const data = await this.commitService.getCommitsByPR(
      project ?? '',
      prIdNumber,
    );

    return CommitsByPRResponseDto.from(data.prId, data.project, data.commits);
  }

  @Get('/tags')
  @ApiOperation({
    summary:
      'Get exact or surrounding tags for a commit; if none are found, return containing branches',
  })
  @ApiQuery({
    description: 'Azure DevOps project name',
    name: 'project',
    required: true,
  })
  @ApiQuery({
    description: 'Repository name',
    name: 'repositoryName',
    required: true,
  })
  @ApiQuery({
    description: 'Commit SHA to search for',
    name: 'commitId',
    required: true,
  })
  @ApiOkResponse({
    description:
      'Exact or surrounding tags returned for commit; when none are found, containing branches are returned',
    type: RepoReferencesResponseDto,
  })
  public async getTagsByCommit(
    @Query() query: CommitTagsQueryDto,
  ): Promise<RepoReferencesResponseDto> {
    return this.commitService.getBranchesAndTagsByCommit(
      query.project,
      query.repositoryName,
      query.commitId,
    );
  }

  @Get('/tags/batch')
  @ApiOperation({
    summary:
      'Batch resolve exact or surrounding tags for multiple commits using main history first, then other branches',
  })
  @ApiQuery({
    description: 'Azure DevOps project name',
    name: 'project',
    required: true,
  })
  @ApiQuery({
    description: 'Repository name',
    name: 'repositoryName',
    required: true,
  })
  @ApiQuery({
    description: 'Comma-separated commit SHAs to resolve (max 100)',
    name: 'commitIds',
    required: true,
  })
  @ApiOkResponse({
    description:
      'Map of commitId to tag context (exactTags, tagAfter, tagBefore, foundInBranch)',
    type: BatchTagsResponseDto,
  })
  public async getTagsByCommitBatch(
    @Query() query: CommitTagsBatchQueryDto,
  ): Promise<BatchTagsResponseDto> {
    return this.commitService.getBranchesAndTagsByCommitBatch(
      query.project,
      query.repositoryName,
      query.commitIds,
    );
  }
}

