export class BatchTagsResponseDto {
  public static from(
    results: Record<string, CommitTagContextDto>,
  ): BatchTagsResponseDto {
    return plainToInstance(BatchTagsResponseDto, {
      results,
      success: true,
    });
  }

  public static fromFailure(
    message: string,
    results: Record<string, CommitTagContextDto> = {},
  ): BatchTagsResponseDto {
    return plainToInstance(BatchTagsResponseDto, {
      message,
      results,
      success: false,
    });
  }

  @ApiProperty({
    additionalProperties: {
      properties: {
        exactTags: { items: { type: 'string' }, type: 'array' },
        foundInBranch: { type: 'boolean' },
        tagAfter: { items: { type: 'string' }, type: 'array' },
        tagBefore: { items: { type: 'string' }, type: 'array' },
      },
      type: 'object',
    },
    type: 'object',
  })
  public results!: Record<string, CommitTagContextDto>;

  @ApiProperty()
  public success!: boolean;

  @ApiProperty({ required: false })
  public message?: string;
}

