import { Transform } from 'class-transformer';
import {
  ArrayMaxSize,
  ArrayNotEmpty,
  IsArray,
  IsNotEmpty,
  IsString,
} from 'class-validator';

export class CommitTagsBatchQueryDto {
  @IsString()
  @IsNotEmpty()
  public project!: string;

  @IsString()
  @IsNotEmpty()
  public repositoryName!: string;

  @Transform(({ value }) => {
    if (Array.isArray(value)) {
      return value.map((commitId) => String(commitId).trim());
    }

    if (typeof value === 'string') {
      return value
        .split(',')
        .map((commitId) => commitId.trim())
        .filter((commitId) => commitId.length > 0);
    }

    return [];
  })
  @IsArray()
  @ArrayNotEmpty()
  @ArrayMaxSize(100)
  @IsString({ each: true })
  @IsNotEmpty({ each: true })
  public commitIds!: Array<string>;
}

