import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { IGitApi } from 'azure-devops-node-api/GitApi';
import { GitRef } from 'azure-devops-node-api/interfaces/GitInterfaces';
import { BatchTagsResponseDto } from '@/commit/dto/batch-tags-response.dto';
import { RepoReferencesResponseDto } from '@/commit/dto/branches-by-commit-response.dto';
import { findMatchingReferenceNames } from '@/commit/utils/commit-reference.utils';
import {
  fetchCommitHistoryFromReference,
  findRepositoryId,
  getTargetCommitInfo,
  resolveTagReferences,
} from '@/commit/utils/tag-resolution.utils';
import {
  buildCommitToTagMap,
  findSurroundingTagsForCommit,
} from '@/commit/utils/tag-selection.utils';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';
import { AzureDevopsService } from '@/config/azure-config/app-azure-devops';

@Injectable()
export class CommitHistoryService {
  private static pickMainBranchRef(
    branchReferences: Array<GitRef>,
  ): GitRef | undefined {
    return branchReferences.find(
      (reference) => reference.name === 'refs/heads/main',
    );
  }

  public constructor(
    private readonly azureDevopsConnection: AzureDevopsService,
    private readonly customLogger: AppLogger,
  ) {}

  private async getGitApi(): Promise<IGitApi> {
    return this.azureDevopsConnection.getGitApi();
  }

  public async getRepoBranchesAndTags(
    project: string,
    repositoryName: string,
  ): Promise<RepoReferencesResponseDto> {
    const context: JobsLogContext = {
      method: 'getRepoBranchesAndTags',
      service: 'CommitHistoryService',
    };

    this.customLogger.log(
      `[SERVICE] Fetching branches and tags for "${repositoryName}" in project "${project}"`,
      context,
    );

    try {
      const gitApi = await this.getGitApi();

      const repositoryId = await findRepositoryId(
        gitApi,
        project,
        repositoryName,
        this.customLogger,
      );

      if (!repositoryId) {
        this.customLogger.warn(
          `[SERVICE] Repository "${repositoryName}" not found in project "${project}"`,
          context,
        );
        return RepoReferencesResponseDto.fromFailure(
          `Repository "${repositoryName}" not found in project "${project}"`,
        );
      }

      const allReferences = await gitApi.getRefs(repositoryId, project);
      const branches = allReferences
        .filter((reference) => reference.name?.startsWith('refs/heads/'))
        .map((reference) =>
          typeof reference.name === 'string'
            ? reference.name.replace('refs/heads/', '')
            : undefined,
        )
        .filter((name): name is string => typeof name === 'string');

      const tags = allReferences
        .filter((reference) => reference.name?.startsWith('refs/tags/'))
        .map((reference) =>
          typeof reference.name === 'string'
            ? reference.name.replace('refs/tags/', '')
            : undefined,
        )
        .filter((name): name is string => typeof name === 'string');

      this.customLogger.log(
        `[SERVICE] Found ${branches.length} branches and ${tags.length} tags for "${repositoryName}"`,
        context,
      );

      return RepoReferencesResponseDto.from(branches, tags);
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to fetch branches and tags for "${repositoryName}" in project "${project}": ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw error;
    }
  }

  /**
   * Resolves exact tags first, then scans only containing branch histories for surrounding tags.
   * Returns containing branches when no exact or surrounding tags are found.
   * @param project Azure DevOps project name.
   * @param repositoryName Repository name.
   * @param commitId Commit SHA to search for.
   * @returns Branch and tag references containing the commit.
   */
  public async getBranchesAndTagsByCommit(
    project: string,
    repositoryName: string,
    commitId: string,
  ): Promise<RepoReferencesResponseDto> {
    const context: JobsLogContext = {
      method: 'getBranchesAndTagsByCommit',
      service: 'CommitHistoryService',
    };

    try {
      this.customLogger.log(
        `[SERVICE] Scanning branches and tags for commit "${commitId}" in "${repositoryName}"`,
        context,
      );

      const gitApi = await this.getGitApi();

      const repositoryId = await findRepositoryId(
        gitApi,
        project,
        repositoryName,
        this.customLogger,
      );
      if (!repositoryId) {
        return RepoReferencesResponseDto.fromFailure(
          `Repository "${repositoryName}" not found in project "${project}"`,
        );
      }

      const allReferences = await gitApi.getRefs(repositoryId, project);
      const tagReferences = allReferences.filter((reference) =>
        reference.name?.startsWith('refs/tags/'),
      );
      const branchReferences = allReferences.filter((reference) =>
        reference.name?.startsWith('refs/heads/'),
      );

      const targetCommitInfo = await getTargetCommitInfo(
        gitApi,
        repositoryId,
        project,
        commitId,
        this.customLogger,
      );
      if (!targetCommitInfo.found) {
        this.customLogger.warn(
          `[SERVICE] Commit "${commitId}" was not found in repository "${repositoryName}": ${targetCommitInfo.errorMessage ?? 'Unknown error'}`,
          context,
        );
        return RepoReferencesResponseDto.fromFailure(
          `Commit "${commitId}" not found in repository "${repositoryName}"`,
        );
      }

      const validResolvedTags = await resolveTagReferences(
        gitApi,
        repositoryId,
        project,
        tagReferences,
        this.customLogger,
      );
      const commitToTagMap = buildCommitToTagMap(validResolvedTags);
      const exactTagNames = commitToTagMap.get(commitId) ?? [];

      const mainBranchReference =
        CommitHistoryService.pickMainBranchRef(branchReferences);

      if (mainBranchReference) {
        const mainBranchHistory = await fetchCommitHistoryFromReference(
          gitApi,
          repositoryId,
          project,
          mainBranchReference.objectId,
          mainBranchReference.name ?? 'refs/heads/main',
          this.customLogger,
        );

        const mainSurroundingTags = findSurroundingTagsForCommit(
          mainBranchHistory,
          commitToTagMap,
          commitId,
        );

        if (mainSurroundingTags) {
          if (exactTagNames.length > 0) {
            const tags = [...new Set(exactTagNames)].map((tagName) =>
              tagName.replace('refs/tags/', ''),
            );

            this.customLogger.log(
              `[SERVICE] Commit "${commitId}" found on main and matched ${tags.length} exact tags. Skipping fallback scan.`,
              context,
            );

            return RepoReferencesResponseDto.from([], tags);
          }

          const surroundingMainTagNames = [
            ...new Set([
              ...mainSurroundingTags.tagAfter,
              ...mainSurroundingTags.tagBefore,
            ]),
          ];

          if (surroundingMainTagNames.length > 0) {
            const tags = surroundingMainTagNames.map((tagName) =>
              tagName.replace('refs/tags/', ''),
            );

            this.customLogger.log(
              `[SERVICE] Commit "${commitId}" found on main and matched ${tags.length} surrounding tags. Skipping fallback scan.`,
              context,
            );

            return RepoReferencesResponseDto.from([], tags);
          }
        }
      }

      if (exactTagNames.length > 0) {
        const tags = [...new Set(exactTagNames)].map((tagName) =>
          tagName.replace('refs/tags/', ''),
        );

        this.customLogger.log(
          `[SERVICE] Commit "${commitId}" matched ${tags.length} exact tags. Skipping branch fallback scan.`,
          context,
        );

        return RepoReferencesResponseDto.from([], tags);
      }

      const branchNames = await findMatchingReferenceNames(
        gitApi,
        repositoryId,
        project,
        branchReferences,
        commitId,
        async (reference) => reference.objectId,
        this.customLogger,
      );
      const branches = branchNames.map((branchName) =>
        branchName.replace('refs/heads/', ''),
      );
      const branchNameSet = new Set(branchNames);
      const matchingBranchReferences = branchReferences.filter(
        (reference) =>
          typeof reference.name === 'string' &&
          branchNameSet.has(reference.name),
      );

      const surroundingTagGroups = await Promise.all(
        matchingBranchReferences.map(async (reference) => {
          const branchHistory = await fetchCommitHistoryFromReference(
            gitApi,
            repositoryId,
            project,
            reference.objectId,
            reference.name ?? 'unknown-branch',
            this.customLogger,
          );

          const surroundingTags = findSurroundingTagsForCommit(
            branchHistory,
            commitToTagMap,
            commitId,
          );

          return [
            ...(surroundingTags?.tagAfter ?? []),
            ...(surroundingTags?.tagBefore ?? []),
          ];
        }),
      );

      const surroundingTagNames = [...new Set(surroundingTagGroups.flat())];

      if (surroundingTagNames.length > 0) {
        const tags = surroundingTagNames.map((tagName) =>
          tagName.replace('refs/tags/', ''),
        );

        this.customLogger.log(
          `[SERVICE] Commit "${commitId}" matched ${tags.length} surrounding tags across ${matchingBranchReferences.length} containing branches.`,
          context,
        );

        return RepoReferencesResponseDto.from([], tags);
      }

      this.customLogger.log(
        `[SERVICE] Commit "${commitId}" had no exact or surrounding tags; fallback branch matches: ${branches.length}`,
        context,
      );

      return RepoReferencesResponseDto.from(branches, []);
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to resolve branch/tag for commit "${commitId}": ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw error;
    }
  }

  /**
   * Batch resolves tags for multiple commits by scanning main first, then other branches.
   * @param project Azure DevOps project name.
   * @param repositoryName Repository name.
   * @param commitIds Commit SHAs to resolve.
   * @returns Map of commitId to exact and surrounding tag context.
   */
  public async getBranchesAndTagsByCommitBatch(
    project: string,
    repositoryName: string,
    commitIds: Array<string>,
  ): Promise<BatchTagsResponseDto> {
    const context: JobsLogContext = {
      method: 'getBranchesAndTagsByCommitBatch',
      service: 'CommitHistoryService',
    };

    try {
      this.customLogger.log(
        `[SERVICE] Resolving tags for ${commitIds.length} commits in "${repositoryName}" using main-first branch history strategy`,
        context,
      );

      if (commitIds.length === 0) {
        return BatchTagsResponseDto.fromFailure(
          'commitIds array cannot be empty',
        );
      }

      if (commitIds.length > 100) {
        return BatchTagsResponseDto.fromFailure(
          'Maximum 100 commits per batch request',
        );
      }

      const gitApi = await this.getGitApi();

      const repositoryId = await findRepositoryId(
        gitApi,
        project,
        repositoryName,
        this.customLogger,
      );

      if (!repositoryId) {
        return BatchTagsResponseDto.fromFailure(
          `Repository "${repositoryName}" not found in project "${project}"`,
        );
      }

      const allReferences = await gitApi.getRefs(repositoryId, project);
      const tagReferences = allReferences.filter((reference) =>
        reference.name?.startsWith('refs/tags/'),
      );

      const resolvedTags = await resolveTagReferences(
        gitApi,
        repositoryId,
        project,
        tagReferences,
        this.customLogger,
      );

      if (resolvedTags.length === 0) {
        return BatchTagsResponseDto.fromFailure(
          `No resolvable tags found in repository "${repositoryName}"`,
        );
      }

      const branchReferences = allReferences.filter((reference) =>
        reference.name?.startsWith('refs/heads/'),
      );

      if (branchReferences.length === 0) {
        return BatchTagsResponseDto.fromFailure(
          `No branches found in repository "${repositoryName}"`,
        );
      }

      const commitToTagMap = buildCommitToTagMap(resolvedTags);
      const results: BatchTagsResponseDto['results'] = {};
      const unresolvedCommitIds = new Set(commitIds);
      const mainBranchReference =
        CommitHistoryService.pickMainBranchRef(branchReferences);
      const remainingBranchReferences = branchReferences
        .filter(
          (reference) =>
            reference.name !== (mainBranchReference?.name ?? 'refs/heads/main'),
        )
        .sort((leftReference, rightReference) => {
          const leftName = leftReference.name ?? '';
          const rightName = rightReference.name ?? '';
          return leftName.localeCompare(rightName);
        });
      const branchScanOrder = [
        ...(mainBranchReference ? [mainBranchReference] : []),
        ...remainingBranchReferences,
      ];
      let foundInBranchCount = 0;
      let scannedBranchCount = 0;

      const scanBranchHistories = async (
        branchIndex: number,
      ): Promise<void> => {
        if (
          branchIndex >= branchScanOrder.length ||
          unresolvedCommitIds.size === 0
        ) {
          return;
        }

        const branchReference = branchScanOrder[branchIndex];
        const branchName = branchReference.name ?? 'unknown-branch';
        const branchHistory = await fetchCommitHistoryFromReference(
          gitApi,
          repositoryId,
          project,
          branchReference.objectId,
          branchName,
          this.customLogger,
        );
        scannedBranchCount += 1;

        const resolvedCommitIds: Array<string> = [];

        for (const commitId of unresolvedCommitIds) {
          const surroundingTags = findSurroundingTagsForCommit(
            branchHistory,
            commitToTagMap,
            commitId,
          );

          if (surroundingTags) {
            const exactTags = commitToTagMap.get(commitId) ?? [];
            const exactTagSet = new Set(exactTags);

            results[commitId] = {
              exactTags: [...new Set(exactTags)].map((tagName) =>
                tagName.replace('refs/tags/', ''),
              ),
              foundInBranch: true,
              tagAfter: [...new Set(surroundingTags.tagAfter)]
                .filter((tagName) => !exactTagSet.has(tagName))
                .map((tagName) => tagName.replace('refs/tags/', '')),
              tagBefore: [...new Set(surroundingTags.tagBefore)].map(
                (tagName) => tagName.replace('refs/tags/', ''),
              ),
            };
            resolvedCommitIds.push(commitId);
            foundInBranchCount += 1;
          }
        }

        for (const commitId of resolvedCommitIds) {
          unresolvedCommitIds.delete(commitId);
        }

        await scanBranchHistories(branchIndex + 1);
      };

      await scanBranchHistories(0);

      for (const commitId of unresolvedCommitIds) {
        results[commitId] = {
          exactTags: [],
          foundInBranch: false,
          tagAfter: [],
          tagBefore: [],
        };
      }

      this.customLogger.log(
        `[SERVICE] Batch tags resolved using main-first branch scan: ${foundInBranchCount}/${commitIds.length} commits found across ${scannedBranchCount} scanned branches`,
        context,
      );

      return BatchTagsResponseDto.from(results);
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to batch resolve tags in "${repositoryName}": ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw error;
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { IGitApi } from 'azure-devops-node-api/GitApi';
import { plainToInstance } from 'class-transformer';
import { CommitInfo } from '../dto/commit-info.dto';
import { CommitsByPRDataDto } from '../dto/commits-by-pr-data.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';
import { AzureDevopsService } from '@/config/azure-config/app-azure-devops';

@Injectable()
export class CommitPRService {
  public constructor(
    private readonly azureDevopsConnection: AzureDevopsService,
    private readonly customLogger: AppLogger,
  ) {}

  private async getGitApi(): Promise<IGitApi> {
    const gitApi = await this.azureDevopsConnection.getGitApi();
    return gitApi;
  }

  public async getCommitsByPR(
    project: string,
    pullRequestId: number,
  ): Promise<CommitsByPRDataDto> {
    const context: JobsLogContext = {
      method: 'getCommitsByPR',
      service: 'CommitPRService',
    };

    try {
      this.customLogger.log(
        `[SERVICE] Fetching commits for PR ${pullRequestId} in project: ${project || 'N/A'}`,
        context,
      );

      const gitApi = await this.getGitApi();
      const pr = await gitApi.getPullRequestById(pullRequestId, project);
      const repoId = pr?.repository?.id;
      const repoName = pr?.repository?.name || 'unknown-repository';

      if (!repoId) {
        this.customLogger.warn(
          `[SERVICE] Repository not found for PR ${pullRequestId}. Returning empty commits map.`,
          context,
        );
        return plainToInstance(CommitsByPRDataDto, {
          commitCount: 0,
          commits: [],
          prId: pullRequestId,
          project: project || 'N/A',
        });
      }

      const commits = await gitApi.getPullRequestCommits(
        repoId,
        pullRequestId,
        project,
      );

      const commitMap = new Map<string, CommitInfo>();
      for (const commit of commits ?? []) {
        if (commit?.commitId) {
          commitMap.set(
            commit.commitId,
            new CommitInfo(commit.commitId, repoName),
          );
        }
      }

      return plainToInstance(CommitsByPRDataDto, {
        commitCount: commitMap.size,
        commits: [...commitMap.values()],
        prId: pullRequestId,
        project: project || 'N/A',
      });
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to fetch commits for PR ${pullRequestId}: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw error;
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { plainToInstance } from 'class-transformer';
import pLimit from 'p-limit';
import { CommitInfo } from '../dto/commit-info.dto';
import { CommitsByPRDataDto } from '../dto/commits-by-pr-data.dto';
import { CommitsByWorkItemDataDto } from '../dto/commits-by-work-item-data.dto';
import { extractCommitIdFromUrl } from '../utils/commit-url.utils';
import { CommitPRService } from './commit-pr.service';
import { extractLinks } from '@/common/azure-devops/work-item-utils';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';
import { WorkItemLink } from '@/work-item/dto/work-item.dto';
import { WorkItemService } from '@/work-item/work-item.service';

@Injectable()
export class CommitWorkItemService {
  public constructor(
    private readonly commitPRService: CommitPRService,
    private readonly workItemService: WorkItemService,
    private readonly customLogger: AppLogger,
  ) {}

  public async getCommitsByWorkitem(
    project: string,
    workItemId: number,
  ): Promise<CommitsByWorkItemDataDto> {
    const context: JobsLogContext = {
      method: 'getCommitsByWorkitem',
      service: 'CommitWorkItemService',
    };

    try {
      this.customLogger.log(
        `[SERVICE] Fetching commits for work item ${workItemId} in project: ${project || 'N/A'}`,
        context,
      );

      const workItem = await this.workItemService.getWorkItemById(workItemId);
      if (!workItem) {
        return plainToInstance(CommitsByWorkItemDataDto, {
          commitCount: 0,
          commits: [],
          project: project || 'N/A',
          workItemId,
        });
      }

      const links: Array<WorkItemLink> = Array.isArray(workItem.links)
        ? workItem.links
        : extractLinks(workItem);

      const commitMap = new Map<string, CommitInfo>();
      const pullRequestIds = new Set<number>();

      for (const link of links) {
        if (link.isPR && link.prId) {
          pullRequestIds.add(link.prId);
        } else if (link.url) {
          const commitId = extractCommitIdFromUrl(link.url, this.customLogger);
          if (commitId) {
            commitMap.set(
              commitId,
              new CommitInfo(commitId, 'unknown-repository'),
            );
          }
        }
      }

      if (pullRequestIds.size > 0) {
        const limit = pLimit(5);
        const prPromises = [...pullRequestIds].map((prId) =>
          limit(async () => {
            try {
              return await this.commitPRService.getCommitsByPR(project, prId);
            } catch (error: unknown) {
              this.customLogger.warn(
                `[SERVICE] Failed to fetch commits for PR ${prId}: ${getErrorMessage(error)}`,
                context,
              );
              return plainToInstance(CommitsByPRDataDto, {
                commitCount: 0,
                commits: [],
                prId,
                project: project || 'N/A',
              });
            }
          }),
        );

        const prResults = await Promise.all(prPromises);
        for (const prData of prResults) {
          for (const commitInfo of prData?.commits ?? []) {
            commitMap.set(commitInfo.commitId, commitInfo);
          }
        }
      }

      return plainToInstance(CommitsByWorkItemDataDto, {
        commitCount: commitMap.size,
        commits: [...commitMap.values()],
        project: project || 'N/A',
        workItemId,
      });
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to fetch commits for work item ${workItemId}: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw error;
    }
  }
}

