import { JobsLogContext } from '@mesx/common-lib';
import { IGitApi } from 'azure-devops-node-api/GitApi';
import {
  GitRef,
  GitVersionType,
} from 'azure-devops-node-api/interfaces/GitInterfaces';
import pLimit from 'p-limit';
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Fallback: use only when getRefs commitId filter is unavailable (older ADO versions).
 * Complexity: O(R × C) — scans each ref's commit history individually.
 * @param gitApi Azure DevOps Git API client.
 * @param repositoryId Repository identifier.
 * @param project Azure DevOps project name.
 * @param referenceCommitId Tip commit SHA for the ref.
 * @param commitId Commit SHA to look for.
 * @returns True when the commit exists in the ref history.
 */
export async function referenceContainsCommit(
  gitApi: IGitApi,
  repositoryId: string,
  project: string,
  referenceCommitId: string | undefined,
  commitId: string,
): Promise<boolean> {
  if (!referenceCommitId) return false;
  if (referenceCommitId === commitId) return true;

  const pageSize = 100;

  const scanPage = async (skip: number): Promise<boolean> => {
    const page = await gitApi.getCommits(
      repositoryId,
      {
        $skip: skip,
        $top: pageSize,
        itemVersion: {
          version: referenceCommitId,
          versionType: GitVersionType.Commit,
        },
      },
      project,
    );

    if (page.length === 0) return false;
    if (page.some((c) => c.commitId === commitId)) return true;
    if (page.length < pageSize) return false;
    return scanPage(skip + pageSize);
  };

  return scanPage(0);
}

/**
 * Fallback: use only when getRefs commitId filter is unavailable (older ADO versions).
 * Wraps referenceContainsCommit for all candidate refs with concurrency control.
 * @param gitApi Azure DevOps Git API client.
 * @param repositoryId Repository identifier.
 * @param project Azure DevOps project name.
 * @param references Candidate refs to scan.
 * @param commitId Commit SHA to look for.
 * @param resolveReferenceCommitId Function that resolves the ref tip commit SHA.
 * @param logger AppLogger used for trace output.
 * @returns The matching ref names.
 */
export async function findMatchingReferenceNamesFallback(
  gitApi: IGitApi,
  repositoryId: string,
  project: string,
  references: Array<GitRef>,
  commitId: string,
  resolveReferenceCommitId: (reference: GitRef) => Promise<string | undefined>,
  logger: AppLogger,
): Promise<Array<string>> {
  const context: JobsLogContext = {
    method: 'findMatchingReferenceNamesFallback',
    service: 'CommitReferenceUtils',
  };
  const limit = pLimit(5);
  const matches = await Promise.all(
    references.map((reference) =>
      limit(async () => {
        const name = reference.name ?? 'unknown-ref';
        const kind = name.startsWith('refs/tags/') ? 'tag' : 'branch';
        const tipCommit = await resolveReferenceCommitId(reference);
        const matched = await referenceContainsCommit(
          gitApi,
          repositoryId,
          project,
          tipCommit,
          commitId,
        );

        logger.log(
          `[SERVICE] ${kind} "${name}" → tip=${tipCommit ?? 'undefined'} → ${matched ? 'MATCH' : 'no match'}`,
          context,
        );

        return matched && reference.name ? reference.name : undefined;
      }),
    ),
  );

  return matches.filter((n): n is string => typeof n === 'string');
}

/**
 * Find all refs whose history contains the target commit.
 * For this SDK version, commitId filtering via getRefs is unavailable,
 * so this delegates to the fallback history scan.
 * @param gitApi Azure DevOps Git API client.
 * @param repositoryId Repository identifier.
 * @param project Azure DevOps project name.
 * @param references Candidate refs to filter results against.
 * @param commitId Commit SHA to look for.
 * @param resolveReferenceCommitId Function that resolves the ref tip commit SHA.
 * @param logger AppLogger used for trace output.
 * @returns The matching ref names.
 */
export async function findMatchingReferenceNames(
  gitApi: IGitApi,
  repositoryId: string,
  project: string,
  references: Array<GitRef>,
  commitId: string,
  resolveReferenceCommitId: (reference: GitRef) => Promise<string | undefined>,
  logger: AppLogger,
): Promise<Array<string>> {
  const context: JobsLogContext = {
    method: 'findMatchingReferenceNames',
    service: 'CommitReferenceUtils',
  };

  logger.log(
    `[SERVICE] commitId ref filter is unavailable in this ADO SDK version; using fallback scan for "${commitId}"`,
    context,
  );

  return findMatchingReferenceNamesFallback(
    gitApi,
    repositoryId,
    project,
    references,
    commitId,
    resolveReferenceCommitId,
    logger,
  );
}

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Extract a commit SHA from a URL string.
 * @param url Raw URL that may contain a commit identifier.
 * @param logger AppLogger used for warning output.
 * @returns The commit SHA when found, or undefined.
 */
export function extractCommitIdFromUrl(
  url: string,
  logger: AppLogger,
): string | undefined {
  const context: JobsLogContext = {
    method: 'extractCommitIdFromUrl',
    service: 'CommitUrlUtils',
  };

  try {
    const decoded = decodeURIComponent(url);
    const patterns = [
      /\/commit\/(\w{7,40})(?:[/?#]|$)/u,
      /\/commits\/(\w{7,40})(?:[/?#]|$)/u,
      /%2F([a-f0-9]{7,40})$/iu,
      /\/([a-f0-9]{7,40})$/iu,
    ];

    for (const pattern of patterns) {
      const match = pattern.exec(decoded);
      if (match?.[1]) {
        return match[1];
      }
    }

    return undefined;
  } catch (error) {
    logger.warn(
      `[SERVICE] Failed to parse commit URL '${url}': ${error ? String(error) : error}`,
      context,
    );
    return undefined;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { IGitApi } from 'azure-devops-node-api/GitApi';
import {
  GitRef,
  GitVersionType,
} from 'azure-devops-node-api/interfaces/GitInterfaces';
import pLimit from 'p-limit';
import {
  CommitHistoryEntry,
  ResolvedTag,
} from '@/commit/utils/tag-selection.utils';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';

interface TargetCommitInfo {
  found: boolean;
  targetDateMs?: number;
  errorMessage?: string;
}

/**
 * Finds a repository ID by its display name in a given Azure DevOps project.
 * @param gitApi Azure DevOps Git API client.
 * @param project Azure DevOps project name.
 * @param repositoryName Repository display name.
 * @param logger AppLogger instance for diagnostics.
 * @returns Repository ID when found, otherwise undefined.
 */
export const findRepositoryId = async (
  gitApi: IGitApi,
  project: string,
  repositoryName: string,
  logger: AppLogger,
): Promise<string | undefined> => {
  const context: JobsLogContext = {
    method: 'findRepositoryId',
    service: 'TagResolutionUtils',
  };

  try {
    const repos = await gitApi.getRepositories(project);
    const repo = repos.find((candidate) => candidate.name === repositoryName);
    return repo?.id;
  } catch (error: unknown) {
    logger.warn(
      `[SERVICE] Failed to find repositoryId for "${repositoryName}" in project "${project}": ${getErrorMessage(error)}`,
      context,
    );
    return undefined;
  }
};

/**
 * Resolves whether the target commit exists and captures its author date in epoch milliseconds.
 * Returns a non-throwing result payload so callers can map not-found to failure DTOs.
 * @param gitApi Azure DevOps Git API client.
 * @param repositoryId Repository ID.
 * @param project Azure DevOps project name.
 * @param commitId Target commit SHA.
 * @param logger AppLogger instance for diagnostics.
 * @returns Object indicating whether commit exists and optional target date/error message.
 */
export const getTargetCommitInfo = async (
  gitApi: IGitApi,
  repositoryId: string,
  project: string,
  commitId: string,
  logger: AppLogger,
): Promise<TargetCommitInfo> => {
  const context: JobsLogContext = {
    method: 'getTargetCommitInfo',
    service: 'TagResolutionUtils',
  };

  try {
    const targetCommit = await gitApi.getCommit(
      commitId,
      repositoryId,
      project,
    );
    return {
      found: true,
      targetDateMs: targetCommit.author?.date
        ? new Date(targetCommit.author.date).getTime()
        : undefined,
    };
  } catch (error: unknown) {
    logger.warn(
      `[SERVICE] Failed to resolve target commit info for commit "${commitId}" in repository "${repositoryId}": ${getErrorMessage(error)}`,
      context,
    );
    return {
      errorMessage: getErrorMessage(error),
      found: false,
    };
  }
};

/**
 * Resolves the commit SHA a tag points to.
 * Supports both annotated tags (via getAnnotatedTag) and lightweight tags (via getCommit fallback).
 * @param gitApi Azure DevOps Git API client.
 * @param tag Tag ref to resolve.
 * @param repositoryId Repository ID.
 * @param project Azure DevOps project name.
 * @param logger AppLogger instance for diagnostics.
 * @returns Commit SHA for the tag, or undefined when unresolved.
 */
export const resolveTagCommit = async (
  gitApi: IGitApi,
  tag: GitRef,
  repositoryId: string,
  project: string,
  logger: AppLogger,
): Promise<string | undefined> => {
  const context: JobsLogContext = {
    method: 'resolveTagCommit',
    service: 'TagResolutionUtils',
  };

  try {
    if (!tag.objectId || !tag.name) {
      logger.log(
        `[SERVICE] Skipping tag with missing metadata: name="${tag.name ?? 'undefined'}", objectId="${tag.objectId ?? 'undefined'}"`,
        context,
      );
      return undefined;
    }

    logger.log(
      `[SERVICE] Resolving annotated tag "${tag.name}" via getAnnotatedTag using objectId "${tag.objectId}"`,
      context,
    );

    try {
      const annotatedTag = await gitApi.getAnnotatedTag(
        project,
        repositoryId,
        tag.objectId,
      );
      const annotatedCommitId = annotatedTag.taggedObject?.objectId;

      if (annotatedCommitId) {
        logger.log(
          `[SERVICE] Annotated tag "${tag.name}" points to commit "${annotatedCommitId}"`,
          context,
        );
        return annotatedCommitId;
      }

      logger.log(
        `[SERVICE] Annotated tag "${tag.name}" did not expose a taggedObject.objectId`,
        context,
      );
    } catch {
      logger.log(
        `[SERVICE] getAnnotatedTag failed for "${tag.name}"; falling back to getCommit`,
        context,
      );
    }

    try {
      logger.log(
        `[SERVICE] Resolving tag "${tag.name}" as lightweight commit using objectId "${tag.objectId}"`,
        context,
      );

      const commit = await gitApi.getCommit(
        tag.objectId,
        repositoryId,
        project,
      );
      if (commit?.commitId) {
        logger.log(
          `[SERVICE] Lightweight tag "${tag.name}" resolved to commit "${commit.commitId}"`,
          context,
        );
        return commit.commitId;
      }

      logger.log(
        `[SERVICE] Lightweight tag lookup for "${tag.name}" returned no commitId`,
        context,
      );
    } catch (error: unknown) {
      logger.warn(
        `[SERVICE] Could not resolve commit for tag "${tag.name}": ${getErrorMessage(error)}`,
        context,
      );
    }

    return undefined;
  } catch (error: unknown) {
    logger.warn(
      `[SERVICE] Unexpected error while resolving tag "${tag.name ?? 'unknown-tag'}": ${getErrorMessage(error)}`,
      context,
    );
    return undefined;
  }
};

/**
 * Resolves all tag refs into normalized tag descriptors containing tag name, commit SHA, and commit date.
 * Invalid/unresolvable refs are skipped and logged.
 * @param gitApi Azure DevOps Git API client.
 * @param repositoryId Repository ID.
 * @param project Azure DevOps project name.
 * @param tagReferences Candidate tag refs.
 * @param logger AppLogger instance for diagnostics.
 * @returns Array of successfully resolved tags.
 */
export const resolveTagReferences = async (
  gitApi: IGitApi,
  repositoryId: string,
  project: string,
  tagReferences: Array<GitRef>,
  logger: AppLogger,
): Promise<Array<ResolvedTag>> => {
  const context: JobsLogContext = {
    method: 'resolveTagReferences',
    service: 'TagResolutionUtils',
  };

  try {
    const limit = pLimit(5);
    const resolvedTags: Array<ResolvedTag | undefined> = await Promise.all(
      tagReferences.map((reference) =>
        limit(async (): Promise<ResolvedTag | undefined> => {
          if (!reference.name) {
            return undefined;
          }

          const tagCommitId = await resolveTagCommit(
            gitApi,
            reference,
            repositoryId,
            project,
            logger,
          );

          if (!tagCommitId) {
            return undefined;
          }

          const tagCommit = await gitApi.getCommit(
            tagCommitId,
            repositoryId,
            project,
          );
          const tagDateMs = tagCommit.author?.date
            ? new Date(tagCommit.author.date).getTime()
            : undefined;

          return {
            name: reference.name,
            tagCommitId,
            tagDateMs,
          };
        }),
      ),
    );

    return resolvedTags.filter((tag): tag is ResolvedTag => tag !== undefined);
  } catch (error: unknown) {
    logger.warn(
      `[SERVICE] Failed resolving tag references: ${getErrorMessage(error)}`,
      context,
    );
    return [];
  }
};

/**
 * Fetches a full newest -> oldest commit history starting from a specific ref tip.
 * This allows the caller to scan only histories that are known to contain the target commit.
 * @param gitApi Azure DevOps Git API client.
 * @param repositoryId Repository ID.
 * @param project Azure DevOps project name.
 * @param referenceCommitId Tip commit SHA for the selected ref.
 * @param referenceName Ref name used for logging.
 * @param logger AppLogger instance for diagnostics.
 * @returns Full commit history for the selected ref, or an empty list when unavailable.
 */
export const fetchCommitHistoryFromReference = async (
  gitApi: IGitApi,
  repositoryId: string,
  project: string,
  referenceCommitId: string | undefined,
  referenceName: string,
  logger: AppLogger,
): Promise<Array<CommitHistoryEntry>> => {
  const context: JobsLogContext = {
    method: 'fetchCommitHistoryFromReference',
    service: 'TagResolutionUtils',
  };

  try {
    if (!referenceCommitId) {
      logger.log(
        `[SERVICE] Skipping history fetch for ref "${referenceName}" because its tip commit is unavailable`,
        context,
      );
      return [];
    }

    logger.log(
      `[SERVICE] Fetching commit history from ref "${referenceName}" (${referenceCommitId})`,
      context,
    );

    const commits: Array<CommitHistoryEntry> = [];
    const pageSize = 100;

    const scanPage = async (skip: number): Promise<void> => {
      const page = await gitApi.getCommits(
        repositoryId,
        {
          $skip: skip,
          $top: pageSize,
          itemVersion: {
            version: referenceCommitId,
            versionType: GitVersionType.Commit,
          },
        },
        project,
      );

      if (page.length === 0) {
        return;
      }

      commits.push(...page.map((commit) => ({ commitId: commit.commitId })));

      if (page.length < pageSize) {
        return;
      }

      await scanPage(skip + pageSize);
    };

    await scanPage(0);

    logger.log(
      `[SERVICE] Retrieved ${commits.length} commits from ref "${referenceName}" history`,
      context,
    );

    return commits;
  } catch (error: unknown) {
    logger.warn(
      `[SERVICE] Failed fetching history for ref "${referenceName}": ${getErrorMessage(error)}`,
      context,
    );
    return [];
  }
};

export interface ResolvedTag {
  name: string;
  tagCommitId: string;
  tagDateMs?: number;
}

export interface CommitHistoryEntry {
  commitId?: string;
}

/**
 * Surrounding tags for a target commit in a linear history walk.
 */
export interface SurroundingTags {
  tagAfter: Array<string>;
  tagBefore: Array<string>;
}

/**
 * Builds a commitId -> tagNames map for the linear history scan.
 * When multiple tags resolve to the same commit, all names are preserved.
 * @param resolvedTags Resolved tag metadata.
 * @returns Commit-to-tag lookup map.
 */
export const buildCommitToTagMap = (
  resolvedTags: Array<ResolvedTag>,
): Map<string, Array<string>> => {
  const commitToTagMap = new Map<string, Array<string>>();

  for (const tag of resolvedTags) {
    const tagNames = commitToTagMap.get(tag.tagCommitId) ?? [];
    tagNames.push(tag.name);
    commitToTagMap.set(tag.tagCommitId, tagNames);
  }

  return commitToTagMap;
};

/**
 * Scans a single newest -> oldest history and returns the nearest tags around the target commit.
 * - tagAfter: the last tag seen at or above the target commit.
 * - tagBefore: the next tag encountered below the target commit.
 * Returns undefined when the target commit is not part of the scanned history.
 * @param commits Full commit history ordered newest -> oldest.
 * @param commitToTagMap Commit-to-tag lookup.
 * @param commitId Target commit SHA.
 * @returns Surrounding tags or undefined when the target is absent from history.
 */
export const findSurroundingTagsForCommit = (
  commits: Array<CommitHistoryEntry>,
  commitToTagMap: Map<string, Array<string>>,
  commitId: string,
): SurroundingTags | undefined => {
  let lastSeenTags: Array<string> = [];

  for (let index = 0; index < commits.length; index += 1) {
    const currentCommitId = commits[index].commitId;
    if (currentCommitId) {
      const tagNames = commitToTagMap.get(currentCommitId) ?? [];
      if (tagNames.length > 0) {
        lastSeenTags = tagNames;
      }

      if (currentCommitId === commitId) {
        let tagBefore: Array<string> = [];

        for (
          let nextIndex = index + 1;
          nextIndex < commits.length;
          nextIndex += 1
        ) {
          const nextCommitId = commits[nextIndex].commitId;
          if (nextCommitId) {
            tagBefore = commitToTagMap.get(nextCommitId) ?? [];
            if (tagBefore.length > 0) {
              break;
            }
          }
        }

        return {
          tagAfter: lastSeenTags,
          tagBefore,
        };
      }
    }
  }

  return undefined;
};

/**
 * Stream Service - Handles SSE (Server-Sent Events) streaming functionality
 * Separated from business logic to follow SOLID principles
 */

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '../logger/app-logger';

type SseMessage = Record<string, unknown>;

interface SseWritableClient {
  write: (chunk: string) => void;
}

interface SseClosableClient {
  end: () => void;
}

type SseClient = SseWritableClient & SseClosableClient;

interface SseHeaderResponse {
  setHeader: (name: string, value: string) => void;
}

interface StreamState {
  activeStream: unknown;
  streamClients: Array<SseClient>;
}
export class StreamService {
  /**
   * Reset stream state
   * @param streamState Current stream state
   * @returns Reset stream state
   */
  public static resetStream(streamState: StreamState): StreamState {
    return {
      ...streamState,
      activeStream: undefined,
      streamClients: [],
    };
  }

  /**
   * Close connection to all SSE clients
   * @param streamClients Connected SSE clients
   */
  public static closeAllClients(streamClients: Array<SseClosableClient>): void {
    for (const client of streamClients) {
      if (client && typeof client.end === 'function') {
        client.end();
      }
    }
  }

  /**
   * Set SSE headers for streaming response
   * @param response Response object for SSE stream
   */
  public static setSseHeaders(response: SseHeaderResponse): void {
    response.setHeader('Content-Type', 'text/event-stream');
    response.setHeader('Cache-Control', 'no-cache');
    response.setHeader('Connection', 'keep-alive');
  }

  /**
   * Broadcast message to all connected SSE clients
   * @param streamClients Connected SSE clients
   * @param message Message payload to broadcast
   * @param logger Logger instance
   */
  public static broadcastToClients(
    streamClients: Array<SseWritableClient>,
    message: SseMessage,
    logger: AppLogger,
  ): void {
    const context: JobsLogContext = {
      method: 'broadcastToClients',
      service: 'StreamService',
    };

    for (const client of streamClients) {
      if (client && typeof client.write === 'function') {
        client.write(`data: ${JSON.stringify(message)}\n\n`);
      } else {
        logger.error('[SSE] Invalid client object', context);
      }
    }
  }

  /**
   * Create batch handler for progressive fetching
   * @param allTasks Accumulator for all fetched tasks
   * @param ids Source id list to fetch
   * @param streamClients Connected SSE clients
   * @param logger Logger instance
   * @returns Batch callback handler
   */
  public static createBatchHandler<T>(
    allTasks: Array<T>,
    ids: Array<string | number>,
    streamClients: Array<SseWritableClient>,
    logger: AppLogger,
  ): (batchItems: Array<T>) => void {
    const context: JobsLogContext = {
      method: 'createBatchHandler',
      service: 'StreamService',
    };

    let batchCount = 0;

    return (batchItems: Array<T>) => {
      batchCount += 1;
      allTasks.push(...batchItems);

      logger.log(
        `[SERVICE] Batch #${batchCount}: ${batchItems.length} items | Total: ${allTasks.length}/${ids.length} | Clients: ${streamClients.length}`,
        context,
      );

      StreamService.broadcastToClients(
        streamClients,
        {
          batch: batchItems,
          batchNumber: batchCount,
          totalLoaded: allTasks.length,
        },
        logger,
      );
    };
  }

  /**
   * Handle streaming completion
   * @param streamState Current stream state
   * @param totalTasks Total tasks fetched
   * @param batchesProcessed Total batches processed
   * @param logger Logger instance
   * @returns Reset stream state
   */
  public static completeStream(
    streamState: StreamState,
    totalTasks: number,
    batchesProcessed: number,
    logger: AppLogger,
  ): StreamState {
    const context: JobsLogContext = {
      method: 'completeStream',
      service: 'StreamService',
    };

    logger.log(`[SSE] ✓ Complete! Total tasks: ${totalTasks}`, context);

    StreamService.broadcastToClients(
      streamState.streamClients,
      {
        batchesProcessed,
        complete: true,
        totalTasks,
      },
      logger,
    );

    StreamService.closeAllClients(streamState.streamClients);

    return StreamService.resetStream(streamState);
  }

  /**
   * Handle streaming error
   * @param streamState Current stream state
   * @param error Streaming error
   * @param logger Logger instance
   * @returns Reset stream state
   */
  public static handleStreamError(
    streamState: StreamState,
    error: Error,
    logger: AppLogger,
  ): StreamState {
    const context: JobsLogContext = {
      method: 'handleStreamError',
      service: 'StreamService',
    };

    logger.error(`[SSE] ✗ Error: ${error.message}`, context);

    StreamService.broadcastToClients(
      streamState.streamClients,
      {
        error: error.message,
      },
      logger,
    );

    StreamService.closeAllClients(streamState.streamClients);

    return StreamService.resetStream(streamState);
  }
}

import {
  WorkItem as AzureWorkItem,
  WorkItemRelation,
} from 'azure-devops-node-api/interfaces/WorkItemTrackingInterfaces';

import { LinkInfo, PRInfo } from '@/pull-request/dto/pull-request.dto';
/**
 * Extracts PR information from a relation object.
 * @param relation The relation object to process
 * @returns PR info containing isPR flag and prId
 */
function extractPRInfo(relation: WorkItemRelation): PRInfo {
  const relationshipType = relation.rel ?? '';
  const url = relation.url ?? '';

  const isPR =
    relationshipType === 'ArtifactLink' && url.includes('PullRequestId');

  if (!isPR) {
    return { isPR: false, prId: undefined };
  }

  const decodedUrl = decodeURIComponent(url);
  // Extract the last number after the final slash using RegExp.exec()
  const execResult = /\/(\d+)$/u.exec(decodedUrl);
  const prId = execResult ? Number.parseInt(execResult[1], 10) : undefined;

  return { isPR: true, prId };
}

/**
 * Extracts link information from work item relations.
 * @param item The work item containing relations
 * @returns Array of link information objects
 */
function extractLinks(item: AzureWorkItem): Array<LinkInfo> {
  if (!item.relations) {
    return [];
  }
  return item.relations.map((relationship: WorkItemRelation) => {
    const { isPR, prId } = extractPRInfo(relationship);

    return {
      isPR,
      prId,
      targetId: relationship.url
        ? relationship.url.split('/').pop()
        : undefined,
      type: relationship.rel,
      url: relationship.url,
    };
  });
}

/**
 * Parses a work item ID from an Azure DevOps relation URL.
 * @param url The relation URL
 * @returns Parsed work item ID if present and numeric
 */
function parseWorkItemIdFromLink(url: string | undefined): number | undefined {
  if (!url) {
    return undefined;
  }

  const maybeId = url.split('/').at(-1);
  if (!maybeId) {
    return undefined;
  }

  const parsed = Number.parseInt(maybeId, 10);
  return Number.isNaN(parsed) ? undefined : parsed;
}

export { extractLinks, extractPRInfo, parseWorkItemIdFromLink };

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class CacheManagerService {
  public static getCacheStats<TKey, TValue>(
    cache: Map<TKey, TValue>,
  ): { size: number } {
    return { size: cache.size };
  }

  public constructor(private readonly customLogger: AppLogger) {}

  public evictIfNeeded<TKey, TValue>(
    cache: Map<TKey, TValue>,
    maxSize: number,
    cacheName: string,
  ): void {
    const context: JobsLogContext = {
      method: 'evictIfNeeded',
      service: 'CacheManagerService',
    };

    if (cache.size > maxSize) {
      const oldestKey = cache.keys().next().value;
      if (oldestKey !== undefined) {
        cache.delete(oldestKey);
        this.customLogger.debug(
          `[CACHE] Evicted oldest entry from ${cacheName} to maintain max size ${maxSize}`,
          context,
        );
      }
    }
  }

  public logCacheHit(cacheKey: string | number, cacheName: string): void {
    const context: JobsLogContext = {
      method: 'logCacheHit',
      service: 'CacheManagerService',
    };

    this.customLogger.debug(
      `[CACHE] Hit for ${cacheName} key: ${cacheKey}`,
      context,
    );
  }

  public logCacheSet(
    cacheKey: string | number,
    cacheName: string,
    itemCount?: number,
  ): void {
    const context: JobsLogContext = {
      method: 'logCacheSet',
      service: 'CacheManagerService',
    };

    const count = itemCount ? ` (${itemCount} items)` : '';
    this.customLogger.debug(
      `[CACHE] Set ${cacheName} key: ${cacheKey}${count}`,
      context,
    );
  }

  public clearCache<TKey, TValue>(
    cache: Map<TKey, TValue>,
    cacheName: string,
  ): void {
    const context: JobsLogContext = {
      method: 'clearCache',
      service: 'CacheManagerService',
    };

    cache.clear();
    this.customLogger.debug(`[CACHE] Cleared ${cacheName}`, context);
  }
}

