/**
 * Normalizes unknown thrown values into a log-friendly message string.
 * @param error Unknown value caught from a try/catch block.
 * @returns Readable error message.
 */
export function getErrorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof error === 'string') return error;

  try {
    return JSON.stringify(error);
  } catch {
    return 'Unknown error';
  }
}

/**
 * Extracts a stack trace from an unknown thrown value when available.
 * @param error Unknown value caught from a try/catch block.
 * @returns Error stack trace or undefined.
 */
export function getErrorStack(error: unknown): string | undefined {
  return error instanceof Error ? error.stack : undefined;
}

