import { AppLogger } from '@/common/logger/app-logger';
import { AppConfigService } from '@/config/app-config/app-config.service';

@Injectable()
export class ApiManagerConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get azureDevopsPatSecretName(): string {
    return this.configService.get<string>('azureDevopsPatSecretName') ?? '';
  }

  public get mainSecretStore(): string {
    return this.configService.get<string>('mainSecretStore') ?? '';
  }

  public get azureDevopsOrg(): string {
    return this.configService.get<string>('azureDevopsOrg') ?? '';
  }

  public get azureDevopsUrl(): string {
    return this.configService.get<string>('azureDevopsUrl') ?? '';
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'ApiManagerConfigService',
    };

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'mainSecretStore', value: this.mainSecretStore },
      { key: 'azureDevopsPatSecretName', value: this.azureDevopsPatSecretName },
      { key: 'azureDevopsOrg', value: this.azureDevopsOrg },
      { key: 'azureDevopsUrl', value: this.azureDevopsUrl },
    ];

    const allEnvironmentValuesArePresent = requiredConfigs.every(
      (config) => `${config.value ?? ''}`.trim().length > 0,
    );

    if (allEnvironmentValuesArePresent) {
      this.customLogger.log(
        'API Manager configuration was provided via environment variables. Skipping App Configuration reachability check.',
        context,
      );
      return;
    }

    if (!(await this.appConfigService.reachable())) {
      const storeNotReachableMessage = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;

      this.customLogger.error(storeNotReachableMessage, context);
      throw new Error(storeNotReachableMessage);
    }

    for (const config of requiredConfigs) {
      if (config.value === undefined || `${config.value}`.trim().length === 0) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }

    this.customLogger.log(
      'All required API Manager configurations are properly set',
      context,
    );
  }
}

import { DaprClient } from '@dapr/dapr';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import * as azdev from 'azure-devops-node-api';
import { ApiManagerConfigService } from './api-manager.service';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class AzureDevopsService implements OnModuleInit {
  private connection!: azdev.WebApi;

  public constructor(
    private readonly appConfigService: ApiManagerConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public async onModuleInit(): Promise<void> {
    const context: JobsLogContext = {
      method: 'onModuleInit',
      service: 'AzureDevopsService',
    };

    const org = this.appConfigService.azureDevopsOrg;
    const baseUrl = this.appConfigService.azureDevopsUrl;
    const daprClient = new DaprClient();
    const secrets = (await daprClient.secret.get(
      this.appConfigService.mainSecretStore,
      this.appConfigService.azureDevopsPatSecretName,
    )) as Record<string, string>;
    const pat = Object.values(secrets)[0];

    if (!org || !pat) {
      throw new Error('Azure DevOps ORG or PAT is missing');
    }

    const orgUrl = `${baseUrl}/${org}`;
    this.connection = new azdev.WebApi(
      orgUrl,
      azdev.getPersonalAccessTokenHandler(pat),
    );
    this.customLogger.log(
      `Azure DevOps connection initialized for org: ${org}`,
      context,
    );
  }

  public getWorkItemTrackingApi(): ReturnType<
    azdev.WebApi['getWorkItemTrackingApi']
  > {
    return this.connection.getWorkItemTrackingApi();
  }

  public getGitApi(): ReturnType<azdev.WebApi['getGitApi']> {
    return this.connection.getGitApi();
  }

  public getCoreApi(): ReturnType<azdev.WebApi['getCoreApi']> {
    return this.connection.getCoreApi();
  }

  public getBuildApi(): ReturnType<azdev.WebApi['getBuildApi']> {
    return this.connection.getBuildApi();
  }
}

