import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { plainToInstance } from 'class-transformer';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';
import { CommitResultDto } from '@/decision/dto/commit-result.dto';
import { DecisionAggregateResultDto } from '@/decision/dto/decision-aggregate-result.dto';
import { DecisionInputSetDto } from '@/decision/dto/decision-input-set.dto';
import { RepoBeforeAfterDto } from '@/decision/dto/repo-before-after.dto';

@Injectable()
export class DecisionAggregateService {
  private static isDone(w: { state?: string | null }): boolean {
    return (w.state ?? '').toLowerCase() === 'done';
  }

  public constructor(private readonly customLogger: AppLogger) {}

  public aggregate(input: DecisionInputSetDto): DecisionAggregateResultDto {
    const context: JobsLogContext = {
      method: 'aggregate',
      service: 'DecisionAggregateService',
    };

    this.customLogger.log(
      `[SERVICE] Starting decision aggregation for ${input.workItems.length} work items and ${input.repositories.length} repositories`,
      context,
    );

    try {
      const doneWorkItems = input.workItems.filter((w) =>
        DecisionAggregateService.isDone(w),
      );

      const otherWorkItems = input.workItems.filter(
        (w) => !DecisionAggregateService.isDone(w),
      );

      const reposWithBeforeAndAfter: Array<RepoBeforeAfterDto> = [];
      const reposWithOnlyBefore: Array<RepoBeforeAfterDto> = [];
      const reposWithOnlyAfter: Array<RepoBeforeAfterDto> = [];

      for (const repo of input.repositories) {
        const name = repo.repositoryName;
        const commits = repo.commits ?? [];

        const repoHasAfter = commits.some(
          (c) =>
            (c.tagAfter ?? []).length > 0 || (c.exactTags ?? []).length > 0,
        );

        const beforeAndAfterCommits: Array<CommitResultDto> = [];
        const onlyBeforeCommits: Array<CommitResultDto> = [];
        const onlyAfterCommits: Array<CommitResultDto> = [];

        for (const c of commits) {
          const tagBefore = c.tagBefore ?? [];
          const tagAfter = c.tagAfter ?? [];
          const exactTags = c.exactTags ?? [];

          const commitResult: CommitResultDto = {
            commitId: c.commitId,
            exactTags,
            tagAfter,
            tagBefore,
          };

          if (tagBefore.length > 0 && tagAfter.length > 0) {
            beforeAndAfterCommits.push(commitResult);
          } else if (tagBefore.length > 0 && tagAfter.length === 0) {
            if (repoHasAfter) commitResult.considerForPR = true;
            onlyBeforeCommits.push(commitResult);
          } else if (tagBefore.length === 0 && tagAfter.length > 0) {
            onlyAfterCommits.push(commitResult);
          }
        }

        if (beforeAndAfterCommits.length > 0) {
          reposWithBeforeAndAfter.push({
            commits: beforeAndAfterCommits,
            repositoryName: name,
          });
        }

        if (onlyBeforeCommits.length > 0) {
          reposWithOnlyBefore.push({
            commits: onlyBeforeCommits,
            repositoryName: name,
          });
        }

        if (onlyAfterCommits.length > 0) {
          reposWithOnlyAfter.push({
            commits: onlyAfterCommits,
            repositoryName: name,
          });
        }
      }

      const aggregateResult = plainToInstance(DecisionAggregateResultDto, {
        doneWorkItems,
        otherWorkItems,
        reposWithBeforeAndAfter,
        reposWithOnlyAfter,
        reposWithOnlyBefore,
      });

      this.customLogger.log(
        `[SERVICE] Decision aggregation completed: ${aggregateResult.doneWorkItems.length} done, ${aggregateResult.otherWorkItems.length} other, ${aggregateResult.reposWithBeforeAndAfter.length} with before/after, ${aggregateResult.reposWithOnlyBefore.length} with only before, ${aggregateResult.reposWithOnlyAfter.length} with only after`,
        context,
      );

      return aggregateResult;
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to aggregate decision input: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );

      throw new InternalServerErrorException(
        'Failed to aggregate decision input',
      );
    }
  }
}

import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import type { NestExpressApplication } from '@nestjs/platform-express';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import * as express from 'express';
import { UrlApiConfigService } from './config/url-api/url-api.service';
import { AppModule } from '@/app.module';
/**
 *
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    rawBody: true,
  });

  app.use(express.json({ type: 'application/cloudevents+json' }));
  // Global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );
  app.use(express.json());
  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });

  const { urlApi } = app.get(UrlApiConfigService);

  const config = new DocumentBuilder()
    .setTitle('Dependency Management Backend API')
    .setDescription(
      'API documentation for the Dependency Management Backend microservice. Contains endpoints.',
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document);
  await app.listen(3000);
}

bootstrap();

