@ApiTags('pullrequests')
@Controller('pullrequests')
@UseFilters(MesGenericErrorFilter)
export class PullRequestController {
  public constructor(
    private readonly pullRequestService: PullRequestService,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Get work items associated with a pull request
   * @param prId - The pull request ID
   * @param project - The Azure DevOps project name
   * @returns Work items associated with the pull request
   */
  @Get(':prId/workitems')
  @ApiOperation({
    summary: 'Get work items associated with a pull request',
  })
  @ApiParam({ description: 'Pull request ID', name: 'prId', type: 'number' })
  @ApiQuery({
    description: 'Azure DevOps project name',
    name: 'project',
    required: false,
  })
  @ApiOkResponse({
    description: 'Work items response',
    type: WorkItemsResponseDto,
  })
  @ApiInternalServerErrorResponse({
    description: 'Failed to fetch work items for PR',
  })
  public async getWorkItemsByPRId(
    @Param('prId') prId: string,
    @Query('project') project?: string,
  ): Promise<WorkItemsResponseDto> {
    const context: JobsLogContext = {
      method: 'getWorkItemsByPRId',
      service: 'PullRequestController',
    };

    const prIdNumber = Number(prId);

    const workItems = await this.pullRequestService.getWorkItemsByPR(
      project ?? '',
      prIdNumber,
    );

    this.customLogger.log(
      `[CONTROLLER] Successfully fetched ${workItems.length} work items for PR ${prIdNumber}`,
      context,
    );

    const response = new WorkItemsResponseDto();
    response.success = true;
    response.data = new WorkItemsDataDto();
    response.data.prId = prIdNumber;
    response.data.project = project || 'N/A';
    response.data.workItemCount = workItems.length;
    response.data.workItems = plainToInstance(WorkItemResultDto, workItems);
    return response;
  }
}

