import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, BadRequestException } from '@nestjs/common';
import { IGitApi } from 'azure-devops-node-api/GitApi';
import { IWorkItemTrackingApi } from 'azure-devops-node-api/WorkItemTrackingApi';
import { GitPullRequest } from 'azure-devops-node-api/interfaces/GitInterfaces';
import {
  WorkItem,
  WorkItemExpand,
} from 'azure-devops-node-api/interfaces/WorkItemTrackingInterfaces';
import {
  LinkInfoDto,
  WorkItemResultDto,
  WorkItemsDataDto,
} from './dto/pull-request.dto';
import { extractLinks } from '@/common/azure-devops/work-item-utils';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';
import { AzureDevopsService } from '@/config/azure-config/app-azure-devops';

@Injectable()
export class PullRequestService {
  public constructor(
    private readonly azureDevopsConnection: AzureDevopsService,
    private readonly customLogger: AppLogger,
  ) {}

  private async getGitApi(): Promise<IGitApi> {
    return this.azureDevopsConnection.getGitApi();
  }

  private async getWorkApi(): Promise<IWorkItemTrackingApi> {
    return this.azureDevopsConnection.getWorkItemTrackingApi();
  }

  private async fetchPRById(
    gitApi: IGitApi,
    pullRequestId: number,
    project?: string,
  ): Promise<GitPullRequest | undefined> {
    const context: JobsLogContext = {
      method: 'fetchPRById',
      service: 'PullRequestService',
    };

    try {
      let repoId: string | undefined;
      if (typeof gitApi.getPullRequestById === 'function') {
        const pr = await gitApi.getPullRequestById(pullRequestId, project);
        repoId = pr?.repository?.id;
        if (pr) return pr;
      }

      if (typeof gitApi.getPullRequest === 'function' && repoId) {
        try {
          return await gitApi.getPullRequest(repoId, pullRequestId, project);
        } catch (error) {
          this.customLogger.warn(
            `Fallback getPullRequest failed for PR ${pullRequestId}: ${getErrorMessage(error)}`,
            context,
          );
          return undefined;
        }
      }

      return undefined;
    } catch (error) {
      this.customLogger.warn(
        `Failed to fetch PR ${pullRequestId}: ${getErrorMessage(error)}`,
        context,
      );
      return undefined;
    }
  }

  /**
   * Get work items linked to a PR.
   * @param project - Azure DevOps project name
   * @param pullRequestId - The pull request ID
   * @returns Array of work items linked to the pull request
   */
  public async getWorkItemsByPR(
    project: string,
    pullRequestId: number,
  ): Promise<Array<WorkItemResultDto>> {
    const context: JobsLogContext = {
      method: 'getWorkItemsByPR',
      service: 'PullRequestService',
    };

    if (!Number.isFinite(pullRequestId)) {
      throw new BadRequestException('Valid PR ID is required');
    }

    try {
      const workItemIds = await this.getWorkItemIdsByPR(project, pullRequestId);
      if (workItemIds.length === 0) {
        return [];
      }

      const workApi = await this.getWorkApi();
      const workItems = await Promise.allSettled(
        workItemIds.map((id) =>
          workApi.getWorkItem(
            id,
            undefined,
            undefined,
            WorkItemExpand.Relations,
          ),
        ),
      );

      return workItems
        .filter(
          (result): result is PromiseFulfilledResult<WorkItem> =>
            result.status === 'fulfilled',
        )
        .map((result) => result.value)
        .filter((item) => item?.id !== undefined)
        .map((item) => {
          const result = new WorkItemResultDto();
          result.id = item.id as number;
          result.title =
            item.fields?.['System.Title'] === undefined
              ? undefined
              : String(item.fields['System.Title']);

          result.links = extractLinks(item).map((link) => {
            const linkDto = new LinkInfoDto();
            linkDto.isPR = link.isPR;
            linkDto.prId = link.prId;
            linkDto.type = link.type;
            linkDto.targetId = link.targetId;
            linkDto.url = link.url;
            return linkDto;
          });

          return result;
        });
    } catch (error) {
      this.customLogger.error(
        `Failed to get work items for PR ${pullRequestId}: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      return [];
    }
  }

  public async getWorkItemsResponseDataByPR(
    pullRequestId: number,
    project?: string,
  ): Promise<WorkItemsDataDto> {
    const context: JobsLogContext = {
      method: 'getWorkItemsResponseDataByPR',
      service: 'PullRequestService',
    };

    const responseData = new WorkItemsDataDto();
    responseData.prId = pullRequestId;
    responseData.project = project || 'N/A';

    try {
      const resolvedProject = project ?? '';
      const workItems = await this.getWorkItemsByPR(
        resolvedProject,
        pullRequestId,
      );

      responseData.workItemCount = workItems.length;
      responseData.workItems = workItems;
      return responseData;
    } catch (error) {
      this.customLogger.error(
        `Failed to build response data for PR ${pullRequestId}: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      responseData.workItemCount = 0;
      responseData.workItems = [];
      return responseData;
    }
  }

  public async getWorkItemIdsByPR(
    project: string,
    pullRequestId: number,
  ): Promise<Array<number>> {
    const context: JobsLogContext = {
      method: 'getWorkItemIdsByPR',
      service: 'PullRequestService',
    };

    try {
      const gitApi = await this.getGitApi();

      const pr = await this.fetchPRById(gitApi, pullRequestId, project);
      const repoId = pr?.repository?.id;

      if (!repoId) {
        return [];
      }

      const references = await gitApi.getPullRequestWorkItemRefs(
        repoId,
        pullRequestId,
        project,
      );

      if (!Array.isArray(references) || references.length === 0) {
        return [];
      }

      const ids = references
        .map((r) => Number(r.id))
        .filter((n): n is number => Number.isFinite(n));

      return [...new Set(ids)];
    } catch (error) {
      this.customLogger.error(
        `Failed to fetch work item IDs for PR ${pullRequestId}: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw error;
    }
  }
}

