import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { WorkItem } from 'azure-devops-node-api/interfaces/WorkItemTrackingInterfaces';
import { Response } from 'express';
import { StreamService } from '../../common/azure-devops/stream.service';
import { AppLogger } from '../../common/logger/app-logger';
import { WorkItemService } from './work-item.service';

@Injectable()
export class StreamManagerService {
  private clients: Array<Response> = [];

  private activeStream = false;

  public constructor(
    private readonly workItemService: WorkItemService,
    private readonly customLogger: AppLogger,
  ) {}

  public addClient(response: Response): void {
    this.clients.push(response);

    // Cleanup on disconnect
    response.once('close', () => {
      this.removeClient(response);
    });
  }

  public removeClient(response: Response): void {
    this.clients = this.clients.filter((c) => c !== response);
  }

  public getClients(): Array<Response> {
    return this.clients;
  }

  public isActive(): boolean {
    return this.activeStream;
  }

  private setActive(value: boolean): void {
    this.activeStream = value;
  }

  public async handleStreamRequest(
    project: string,
    response: Response,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleStreamRequest',
      service: 'StreamManagerService',
    };

    StreamService.setSseHeaders(response);
    this.addClient(response);

    if (this.isActive()) {
      this.customLogger.log(
        `[SSE] Reusing stream. Clients: ${this.getClients().length}`,
        context,
      );
      return;
    }

    this.setActive(true);
    this.customLogger.log(
      `[SSE] Stream started for project: ${project}`,
      context,
    );

    const clients = this.getClients();

    try {
      this.customLogger.log(`[SSE] Fetching task IDs...`, context);
      const ids = (await this.workItemService.getTaskIds(project)) ?? [];
      this.customLogger.log(`[SSE] Found ${ids.length} task IDs`, context);

      const allTasks: Array<WorkItem> = [];
      const onBatch = StreamService.createBatchHandler(
        allTasks,
        ids,
        clients,
        this.customLogger,
      );

      this.customLogger.log(`[SSE] Starting to fetch work items...`, context);
      await this.workItemService.getWorkItems(ids, 200, onBatch);

      StreamService.completeStream(
        { activeStream: true, streamClients: clients },
        allTasks.length,
        Math.ceil(ids.length / 200),
        this.customLogger,
      );
    } catch (error) {
      StreamService.handleStreamError(
        { activeStream: true, streamClients: this.getClients() },
        error as Error,
        this.customLogger,
      );
      this.customLogger.error(`Error in stream: ${error}`, context);
    } finally {
      this.setActive(false);
      this.clients = [];
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import pLimit from 'p-limit';
import { CommitInfo } from '@/commit/dto/commit-info.dto';
import { extractCommitIdFromUrl } from '@/commit/utils/commit-url.utils';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';
import { AzureDevopsService } from '@/config/azure-config/app-azure-devops';
import { WorkItem } from '@/work-item/dto/work-item.dto';

@Injectable()
export class WorkItemCommitService {
  public constructor(
    private readonly azureDevopsConnection: AzureDevopsService,
    private readonly customLogger: AppLogger,
  ) {}

  public async aggregateRelatedCommits(
    project: string,
    workItems: Array<WorkItem>,
    visitedPrIds: Set<number>,
  ): Promise<Array<CommitInfo>> {
    const context: JobsLogContext = {
      method: 'aggregateRelatedCommits',
      service: 'WorkItemCommitService',
    };

    try {
      const commitMap = new Map<string, CommitInfo>();
      this.collectCommitsFromWorkItems(workItems, commitMap);
      await this.collectCommitsFromVisitedPrs(project, visitedPrIds, commitMap);

      return [...commitMap.values()];
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to aggregate related commits: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      return [];
    }
  }

  private collectCommitsFromWorkItems(
    workItems: Array<WorkItem>,
    commitMap: Map<string, CommitInfo>,
  ): void {
    for (const workItem of workItems) {
      for (const link of workItem.links ?? []) {
        if (link.url) {
          const commitId = extractCommitIdFromUrl(link.url, this.customLogger);
          if (commitId) {
            commitMap.set(
              commitId,
              new CommitInfo(commitId, 'unknown-repository'),
            );
          }
        }
      }
    }
  }

  private async collectCommitsFromVisitedPrs(
    project: string,
    visitedPrIds: Set<number>,
    commitMap: Map<string, CommitInfo>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'collectCommitsFromVisitedPrs',
      service: 'WorkItemCommitService',
    };

    if (visitedPrIds.size === 0) {
      return;
    }

    const gitApi = await this.azureDevopsConnection.getGitApi();
    const limit = pLimit(5);

    await Promise.all(
      [...visitedPrIds].map((prId) =>
        limit(async () => {
          try {
            const pullRequest = await gitApi.getPullRequestById(prId, project);
            const repoId = pullRequest?.repository?.id;
            const repoName =
              pullRequest?.repository?.name ?? 'unknown-repository';

            if (!repoId) {
              this.customLogger.warn(
                `[SERVICE] Repository not found while loading commits for PR ${prId}`,
                context,
              );
              return;
            }

            const commits = await gitApi.getPullRequestCommits(
              repoId,
              prId,
              project,
            );

            for (const commit of commits ?? []) {
              if (commit?.commitId) {
                commitMap.set(
                  commit.commitId,
                  new CommitInfo(commit.commitId, repoName),
                );
              }
            }
          } catch (error: unknown) {
            this.customLogger.warn(
              `[SERVICE] Failed to load commits for visited PR ${prId}: ${getErrorMessage(error)}`,
              context,
            );
          }
        }),
      ),
    );
  }
}

