import { WorkItemCommitService } from './work-item-commit.service';
import { AppLogger } from '@/common/logger/app-logger';
import { getErrorMessage } from '@/common/logger/error-message.util';
import { AzureDevopsService } from '@/config/azure-config/app-azure-devops';
import { PullRequestService } from '@/pull-request/pull-request.service';

@Injectable()
export class WorkItemService {
  private static asSortedUnique(values: Set<number>): Array<number> {
    return [...values].sort((left, right) => left - right);
  }

  private readonly maxCacheSize = 1000;

  private readonly maxPrCacheSize = 1000;

  private readonly workItemCache = new Map<number, WorkItem>();

  public constructor(
    private readonly azureDevopsConnection: AzureDevopsService,
    private readonly pullRequestService: PullRequestService,
    private readonly workItemCommitService: WorkItemCommitService,
    private readonly cacheManager: CacheManagerService,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Get the Azure DevOps work item tracking API client.
   * @returns A configured work item tracking API instance.
   */
  private async getWorkApi(): Promise<WorkItemTrackingApi> {
    return this.azureDevopsConnection.getWorkItemTrackingApi();
  }

  /**
   * Get task, bug, and user story IDs for a project.
   * @param project - Azure DevOps project name.
   * @returns Matching work item IDs, or an empty array on failure.
   */
  public async getTaskIds(project: string): Promise<Array<number> | undefined> {
    const context: JobsLogContext = {
      method: 'getTaskIds',
      service: 'WorkItemService',
    };

    try {
      const workApi = await this.getWorkApi();
      const wiql = {
        query: `
          SELECT [System.Id]
          FROM WorkItems
          WHERE [System.TeamProject] = '${project}'
          AND ([System.WorkItemType] = 'TASK' OR [System.WorkItemType] = 'Bug' OR [System.WorkItemType] = 'User Story')
          ORDER BY [System.ChangedDate] DESC
        `,
      };
      const result = await workApi.queryByWiql(wiql);
      const taskIds =
        result.workItems
          ?.map((w) => w.id)
          .filter((id): id is number => id !== undefined) ?? [];
      this.customLogger.log(
        `[SERVICE] Successfully fetched ${taskIds.length} task IDs from project '${project}'`,
        context,
      );
      return taskIds;
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to fetch task IDs for project '${project}': ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      return [];
    }
  }

  /**
   * Fetch work items in batches and map them into the local DTO shape.
   * @param ids - Work item IDs to fetch.
   * @param batchSize - Number of IDs per Azure DevOps request.
   * @param onBatchFetched - Optional callback invoked after each batch is fetched.
   * @returns All fetched work items.
   */
  public async getWorkItems(
    ids: Array<number> | undefined,
    batchSize = 200,
    onBatchFetched?: (items: Array<WorkItem>) => void,
  ): Promise<Array<WorkItem>> {
    const context: JobsLogContext = {
      method: 'getWorkItems',
      service: 'WorkItemService',
    };

    try {
      const workApi = await this.getWorkApi();
      const items: Array<WorkItem> = [];
      this.customLogger.log(
        `[SERVICE] Starting to fetch ${ids?.length ?? 0} work items with batch size: ${batchSize}`,
        context,
      );

      if (!ids || ids.length === 0) {
        this.customLogger.warn(
          '[SERVICE] No IDs provided to fetch work items.',
          context,
        );
        return items;
      }

      const batches = [];
      for (let index = 0; index < ids.length; index += batchSize) {
        const batch = ids.slice(index, index + batchSize);
        batches.push(batch);
      }

      // Fetch all batches concurrently
      const batchPromises = batches.map(async (batch, batchIndex) => {
        const batchNumber = batchIndex + 1;
        this.customLogger.log(
          `[SERVICE] Processing batch #${batchNumber}: IDs ${batch[0]} to ${batch.at(-1)}`,
          context,
        );

        const request = {
          $expand: WorkItemExpand.Relations,
          ids: batch,
        };

        let data;
        try {
          data = await workApi.getWorkItemsBatch(request);
          this.customLogger.log(
            `[SERVICE] Batch #${batchNumber} fetched successfully: ${data.length} items`,
            context,
          );
        } catch (error: unknown) {
          this.customLogger.warn(
            `[SERVICE] Batch #${batchNumber} failed, retrying... ${getErrorMessage(error)}`,
            context,
          );
          try {
            data = await workApi.getWorkItemsBatch(request);
            this.customLogger.log(
              `[SERVICE] Batch #${batchNumber} retry successful: ${data.length} items`,
              context,
            );
          } catch (batchError: unknown) {
            this.customLogger.error(
              `[SERVICE] Batch #${batchNumber} failed permanently`,
              context,
              batchError instanceof Error
                ? batchError
                : new Error(getErrorMessage(batchError)),
            );
            throw new Error(
              `getWorkItemsBatch failed: ${getErrorMessage(batchError)}`,
            );
          }
        }

        const batchItems = data.map((item) => ({
          assignedTo: item.fields?.['System.AssignedTo']
            ? item.fields['System.AssignedTo'].displayName
            : 'Unassigned',
          id: item.id,
          links: extractLinks(item),

          state: item.fields?.['System.State'],

          title: item.fields?.['System.Title'],

          type: item.fields?.['System.WorkItemType'],
        }));

        items.push(...batchItems);

        if (onBatchFetched && typeof onBatchFetched === 'function') {
          this.customLogger.log(
            `[SERVICE] Calling batch callback for batch #${batchNumber}`,
            context,
          );
          onBatchFetched(batchItems);
        }
      });

      // Wait for all batches to complete
      await Promise.all(batchPromises);

      this.customLogger.log(
        `[SERVICE] ✓ Completed fetching all ${items.length} work items`,
        context,
      );
      return items;
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to fetch work items: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw new InternalServerErrorException(
        'Failed to fetch work items from Azure DevOps',
      );
    }
  }

  /**
   * Fetch a single work item by ID, using the in-memory cache when enabled.
   * @param workItemId - Work item ID to fetch.
   * @param useCache - Whether to read and write from the cache.
   * @returns The mapped work item, or undefined if it cannot be loaded.
   */
  public async getWorkItemById(
    workItemId: number,
    useCache = true,
  ): Promise<WorkItem> {
    const context: JobsLogContext = {
      method: 'getWorkItemById',
      service: 'WorkItemService',
    };

    if (!Number.isFinite(workItemId)) {
      throw new BadRequestException('Valid work item ID is required');
    }

    try {
      if (useCache && this.workItemCache.has(workItemId)) {
        this.cacheManager.logCacheHit(workItemId, 'work-item-cache');
        return this.workItemCache.get(workItemId) as WorkItem;
      }

      const workApi = await this.getWorkApi();

      const item = await workApi.getWorkItem(
        workItemId,
        undefined,
        undefined,
        WorkItemExpand.Relations,
      );

      if (!item?.fields) {
        this.customLogger.warn(
          `[SERVICE] Work item ${workItemId} has no fields or does not exist`,
          context,
        );
        throw new NotFoundException(`Work item ${workItemId} not found`);
      }

      const result = {
        assignedTo: item.fields['System.AssignedTo']
          ? item.fields['System.AssignedTo'].displayName
          : 'Unassigned',
        id: item.id,
        links: extractLinks(item),
        state: item.fields['System.State'],
        title: item.fields['System.Title'],
        type: item.fields['System.WorkItemType'],
      };

      if (useCache) {
        this.workItemCache.set(workItemId, result);
        this.cacheManager.logCacheSet(workItemId, 'work-item-cache');
        this.cacheManager.evictIfNeeded(
          this.workItemCache,
          this.maxCacheSize,
          'work-item-cache',
        );
      }

      return result;
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to fetch work item ${workItemId}: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw new NotFoundException(`Work item ${workItemId} not found`);
    }
  }

  /**
   * Fetch a batch of work items, returning an empty array for empty input.
   * @param ids - Work item IDs to fetch.
   * @returns The fetched work items.
   */
  private async fetchWorkItemsBatch(
    ids: Array<number>,
  ): Promise<Array<WorkItem>> {
    if (ids.length === 0) return [];
    return this.getWorkItems(ids);
  }

  /**
   * Expand pull requests into related work item IDs with bounded concurrency.
   * @param prIds - Pull request IDs to expand.
   * @param project - Azure DevOps project name.
   * @param cache - Traversal cache for PR-to-work-item results.
   * @returns Work item IDs discovered from the pull requests.
   */
  private async expandPullRequests(
    prIds: Array<number>,
    project: string,
    cache: Map<number, Array<number>>,
  ): Promise<Array<number>> {
    const context: JobsLogContext = {
      method: 'expandPullRequests',
      service: 'WorkItemService',
    };

    try {
      const limit = pLimit(5);

      const results = await Promise.all(
        prIds.map((prId) =>
          limit(async () => {
            if (cache.has(prId)) {
              this.cacheManager.logCacheHit(prId, 'pr-work-items-cache');
              return cache.get(prId)?.slice() ?? [];
            }

            try {
              const ids = await this.pullRequestService.getWorkItemIdsByPR(
                project,
                prId,
              );

              cache.set(prId, ids);
              this.cacheManager.logCacheSet(
                prId,
                'pr-work-items-cache',
                ids.length,
              );
              this.cacheManager.evictIfNeeded(
                cache,
                this.maxPrCacheSize,
                'pr-work-items-cache',
              );
              return ids;
            } catch (error: unknown) {
              this.customLogger.warn(
                `[SERVICE] Failed to expand PR ${prId}: ${getErrorMessage(error)}`,
                context,
              );
              return [];
            }
          }),
        ),
      );

      return results.flat();
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to expand pull requests: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      return [];
    }
  }

  private async getRootsOrFail(
    rootWorkItemIds: Array<number>,
  ): Promise<Array<WorkItem>> {
    const rootItems = await this.fetchWorkItemsBatch(rootWorkItemIds);
    const foundRootIds = new Set(
      rootItems
        .map((workItem) => workItem.id)
        .filter((workItemId): workItemId is number =>
          Number.isFinite(workItemId),
        ),
    );
    const missingRootIds = rootWorkItemIds.filter(
      (workItemId) => !foundRootIds.has(workItemId),
    );

    if (missingRootIds.length > 0) {
      throw new NotFoundException(
        `Work item${missingRootIds.length > 1 ? 's' : ''} ${missingRootIds.join(', ')} not found`,
      );
    }

    return rootItems;
  }

  /**
   * Resolve PR-linked work item IDs for the current traversal level.
   * @param presentItems - Work items present at the current level.
   * @param project - Azure DevOps project name.
   * @param prToWorkItemIds - Traversal cache for PR expansion results.
   * @param visitedPrIds - Set of visited pull request IDs.
   * @returns Related work item IDs found through pull requests.
   */
  private async getPrRelatedIdsForLevel(
    presentItems: Array<WorkItem>,
    project: string,
    prToWorkItemIds: Map<number, Array<number>>,
    visitedPrIds: Set<number>,
  ): Promise<Array<number>> {
    const context: JobsLogContext = {
      method: 'getPrRelatedIdsForLevel',
      service: 'WorkItemService',
    };

    try {
      const prIds = extractUniquePrIds(presentItems);
      if (prIds.length === 0) {
        return [];
      }

      for (const prId of prIds) {
        visitedPrIds.add(prId);
      }

      this.customLogger.log(
        `[SERVICE] Expanding ${prIds.length} pull request(s) for related items`,
        context,
      );
      const prRelatedIds = await this.expandPullRequests(
        prIds,
        project,
        prToWorkItemIds,
      );
      this.customLogger.log(
        `[SERVICE] Found ${prRelatedIds.length} work items related to pull requests`,
        context,
      );

      return prRelatedIds;
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Failed to get PR-related IDs for current level: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      return [];
    }
  }

  /**
   * Register newly discovered IDs so traversal does not revisit them.
   * @param discoveredIds - Set of already discovered work item IDs.
   * @param nextLevelIds - IDs discovered for the next traversal level.
   */
  private addDiscoveredIds(
    discoveredIds: Set<number>,
    nextLevelIds: Array<number>,
  ): void {
    for (const id of nextLevelIds) {
      discoveredIds.add(id);
    }

    const context: JobsLogContext = {
      method: 'addDiscoveredIds',
      service: 'WorkItemService',
    };

    this.customLogger.debug(
      `[SERVICE] Added ${nextLevelIds.length} newly discovered work item ID(s)`,
      context,
    );
  }

  /**
   * Process one traversal level, collect present items, expand PR links, and recurse.
   * @param levelIds - Work item IDs to process at this level.
   * @param project - Azure DevOps project name.
   * @param fetchedWorkItems - Cache of work items already fetched in this traversal.
   * @param prToWorkItemIds - Cache of PR expansion results.
   * @param visitedPrIds - Set of visited pull request IDs.
   * @param discoveredIds - Set of IDs already discovered across all levels.
   * @param results - Accumulator for returned work items.
   */
  private async traverseLevel(
    levelIds: Array<number>,
    project: string,
    fetchedWorkItems: Map<number, WorkItem>,
    prToWorkItemIds: Map<number, Array<number>>,
    visitedPrIds: Set<number>,
    discoveredIds: Set<number>,
    results: Array<WorkItem>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'traverseLevel',
      service: 'WorkItemService',
    };

    try {
      if (levelIds.length === 0) {
        return;
      }

      const idsToFetch = levelIds.filter((id) => !fetchedWorkItems.has(id));

      if (idsToFetch.length === 0) {
        this.customLogger.debug(
          `[SERVICE] No new IDs to fetch at this level (all cached)`,
          context,
        );
      } else {
        this.customLogger.log(
          `[SERVICE] Fetching ${idsToFetch.length} work items in current traversal level`,
          context,
        );
        const fetchedItems = await this.fetchWorkItemsBatch(idsToFetch);

        cacheFetchedWorkItems(fetchedItems, fetchedWorkItems);
      }

      const presentItems = getPresentLevelItems(levelIds, fetchedWorkItems);
      if (presentItems.length === 0) {
        this.customLogger.warn(
          `[SERVICE] No work items available to process for current traversal level`,
          context,
        );
        return;
      }

      results.push(...presentItems);

      const prRelatedIds = await this.getPrRelatedIdsForLevel(
        presentItems,
        project,
        prToWorkItemIds,
        visitedPrIds,
      );

      const nextLevelIds = computeNextLevelIds(
        presentItems,
        prRelatedIds,
        discoveredIds,
      );

      this.addDiscoveredIds(discoveredIds, nextLevelIds);

      await this.traverseLevel(
        nextLevelIds,
        project,
        fetchedWorkItems,
        prToWorkItemIds,
        visitedPrIds,
        discoveredIds,
        results,
      );
    } catch (error: unknown) {
      this.customLogger.error(
        `[SERVICE] Error during traversal of work item relations: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw error;
    }
  }

  /**
   * Get all work items related to a root work item through children and PR links.
   * @param rootWorkItemId - Root work item ID.
   * @param project - Optional Azure DevOps project name used for PR expansion.
   * @returns All related work items, or an empty array on non-not-found failure.
   */
  public async getRelatedWorkItems(
    rootWorkItemId: number,
    project = '',
  ): Promise<{
    workItems: Array<WorkItem>;
    visitedPullRequestIds: Array<number>;
    commits: Array<CommitInfo>;
  }> {
    const relatedData = await this.getRelatedWorkItemsByIds(
      [rootWorkItemId],
      project,
    );

    return {
      commits: relatedData.commits,
      visitedPullRequestIds: relatedData.visitedPullRequestIds,
      workItems: relatedData.workItems,
    };
  }

  public async getRelatedWorkItemsByIds(
    rootWorkItemIds: Array<number>,
    project = '',
  ): Promise<{
    requestedWorkItemIds: Array<number>;
    workItems: Array<WorkItem>;
    visitedPullRequestIds: Array<number>;
    commits: Array<CommitInfo>;
  }> {
    const context: JobsLogContext = {
      method: 'getRelatedWorkItemsByIds',
      service: 'WorkItemService',
    };

    try {
      const normalizedRootIds = normalizeRootWorkItemIds(rootWorkItemIds);
      const rootItems = await this.getRootsOrFail(normalizedRootIds);

      const discoveredIds = new Set<number>(normalizedRootIds);
      const results: Array<WorkItem> = [];
      const visitedPrIds = new Set<number>();

      const fetchedWorkItems = new Map<number, WorkItem>();
      const prToWorkItemIds = new Map<number, Array<number>>();

      cacheFetchedWorkItems(rootItems, fetchedWorkItems);

      await this.traverseLevel(
        normalizedRootIds,
        project,
        fetchedWorkItems,
        prToWorkItemIds,
        visitedPrIds,
        discoveredIds,
        results,
      );

      const commits = await this.workItemCommitService.aggregateRelatedCommits(
        project,
        results,
        visitedPrIds,
      );
      const visitedPullRequestIds =
        WorkItemService.asSortedUnique(visitedPrIds);

      this.customLogger.log(
        `[SERVICE] ✓ Completed related work items traversal for ${normalizedRootIds.length} root work item(s). Found ${results.length} work items, ${visitedPullRequestIds.length} visited PRs, ${commits.length} commits.`,
        context,
      );
      return {
        commits,
        requestedWorkItemIds: normalizedRootIds,
        visitedPullRequestIds,
        workItems: results,
      };
    } catch (error: unknown) {
      if (
        error instanceof NotFoundException ||
        error instanceof BadRequestException
      ) {
        throw error;
      }
      this.customLogger.error(
        `[SERVICE] Fatal error in getRelatedWorkItemsByIds: ${getErrorMessage(error)}`,
        context,
        error instanceof Error ? error : undefined,
      );
      throw new InternalServerErrorException(
        'Failed to fetch related work items',
      );
    }
  }
}

import { BadRequestException } from '@nestjs/common';
import { parseWorkItemIdFromLink } from '../../common/azure-devops/work-item-utils';
import { WorkItem } from '../dto/work-item.dto';

/**
 * Normalizes and validates the requested root work item IDs.
 * @param rootWorkItemIds Root work item IDs requested by the caller.
 * @returns Unique finite work item IDs.
 */
function normalizeRootWorkItemIds(
  rootWorkItemIds: Array<number>,
): Array<number> {
  const normalizedRootIds = [...new Set(rootWorkItemIds)].filter((workItemId) =>
    Number.isFinite(workItemId),
  );

  if (normalizedRootIds.length === 0) {
    throw new BadRequestException(
      'At least one valid work item ID is required',
    );
  }

  return normalizedRootIds;
}

/**
 * Extracts unique child work item IDs from hierarchy-forward links.
 * @param item Work item whose links are scanned.
 * @returns Unique child work item IDs.
 */
function getChildWorkItemIdsFromLinks(item: WorkItem): Array<number> {
  const links = item.links ?? [];

  const ids = links
    .filter((link) => link.type === 'System.LinkTypes.Hierarchy-Forward')
    .map((link) => parseWorkItemIdFromLink(link.url))
    .filter((id): id is number => id !== undefined);

  return [...new Set(ids)];
}

/**
 * Extracts unique pull request IDs from work item links.
 * @param item Work item whose links are scanned.
 * @returns Unique pull request IDs.
 */
function getPullRequestIdsFromLinks(item: WorkItem): Array<number> {
  const links = item.links ?? [];

  const prIds = links
    .filter((link) => link.isPR)
    .map((link) => link.prId)
    .filter((prId): prId is number => prId !== undefined);

  return [...new Set(prIds)];
}

/**
 * Stores fetched work items in a per-traversal cache keyed by work item ID.
 * @param items Work items fetched for the current traversal step.
 * @param cache Cache keyed by work item ID.
 */
function cacheFetchedWorkItems(
  items: Array<WorkItem>,
  cache: Map<number, WorkItem>,
): void {
  for (const item of items) {
    if (item.id !== undefined) {
      cache.set(item.id, item);
    }
  }
}

/**
 * Resolves the current level IDs against the cache and returns only present items.
 * @param ids Work item IDs for the current traversal level.
 * @param cache Cache keyed by work item ID.
 * @returns Work items that are present in cache for this level.
 */
function getPresentLevelItems(
  ids: Array<number>,
  cache: Map<number, WorkItem>,
): Array<WorkItem> {
  return ids
    .map((id) => cache.get(id))
    .filter((item): item is WorkItem => item !== undefined);
}

/**
 * Computes unique pull request IDs linked from the given work items.
 * @param items Work items to inspect.
 * @returns Unique pull request IDs.
 */
function extractUniquePrIds(items: Array<WorkItem>): Array<number> {
  const prIds = items.flatMap((item) => getPullRequestIdsFromLinks(item));

  return [...new Set(prIds)];
}

/**
 * Builds the next traversal level by merging child and PR-related IDs,
 * deduplicating them, and excluding IDs already discovered.
 * @param items Work items in the current traversal level.
 * @param prRelatedIds Work item IDs discovered via PR links.
 * @param discovered Set of already-seen work item IDs.
 * @returns Unique undiscovered IDs for the next level.
 */
function computeNextLevelIds(
  items: Array<WorkItem>,
  prRelatedIds: Array<number>,
  discovered: Set<number>,
): Array<number> {
  const childIds = items.flatMap((item) => getChildWorkItemIdsFromLinks(item));

  const combined = [...childIds, ...prRelatedIds];

  const unique = [...new Set(combined)];

  return unique.filter((id) => !discovered.has(id));
}

export {
  cacheFetchedWorkItems,
  computeNextLevelIds,
  extractUniquePrIds,
  getPresentLevelItems,
  normalizeRootWorkItemIds,
};

import { JobsLogContext } from '@mesx/common-lib';
import { Controller, Get, Param, Query, Res, UseFilters } from '@nestjs/common';
import {
  ApiInternalServerErrorResponse,
  ApiOkResponse,
  ApiOperation,
  ApiParam,
  ApiQuery,
  ApiTags,
} from '@nestjs/swagger';
import { plainToInstance } from 'class-transformer';
import { Response } from 'express';
import { CommitInfo } from '@/commit/dto/commit-info.dto';
import { MesGenericErrorFilter } from '@/common/filters/mes-generic-error.filter';
import { AppLogger } from '@/common/logger/app-logger';
import { RelatedWorkItemsBatchDataDto } from '@/work-item/dto/related-work-items-batch-data.dto';
import { RelatedWorkItemsBatchQueryDto } from '@/work-item/dto/related-work-items-batch-query.dto';
import { RelatedWorkItemsBatchResponseDto } from '@/work-item/dto/related-work-items-batch-response.dto';
import { RelatedWorkItemsDataDto } from '@/work-item/dto/related-work-items-data.dto';
import { RelatedWorkItemsResponseDto } from '@/work-item/dto/related-work-items-response.dto';
import { WorkItemResponseDto } from '@/work-item/dto/work-item-response.dto';
import { WorkItemDto } from '@/work-item/dto/work-item.dto';
import { StreamManagerService } from '@/work-item/service/stream-manager-service';
import { WorkItemService } from '@/work-item/service/work-item.service';

@ApiTags('workitem')
@Controller('workitem')
@UseFilters(MesGenericErrorFilter)
export class WorkItemController {
  public constructor(
    private readonly workItemService: WorkItemService,
    private readonly streamManagerService: StreamManagerService,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Get all tasks with progressive batches (SSE streaming)
   * @param response The HTTP response object used for SSE streaming
   */
  @Get('/tasks/stream')
  @ApiOperation({ summary: 'Stream tasks (SSE)' })
  @ApiOkResponse({ description: 'SSE stream of tasks' })
  public async getTasksStream(@Res() response: Response): Promise<void> {
    const project = 'MES_X.0';
    await this.streamManagerService.handleStreamRequest(project, response);
  }

  @Get('/related')
  @ApiOperation({ summary: 'Get related work items by multiple IDs' })
  @ApiQuery({
    description: 'Comma-separated root work item IDs (max 100)',
    name: 'workItemIds',
    required: true,
    type: String,
  })
  @ApiQuery({
    description: 'Optional Azure DevOps project name',
    name: 'project',
    required: false,
    type: String,
  })
  @ApiOkResponse({
    description: 'Related work items returned for all requested roots',
    type: RelatedWorkItemsBatchResponseDto,
  })
  @ApiInternalServerErrorResponse({
    description: 'Failed to fetch related work items',
  })
  public async getRelatedWorkItemsByIds(
    @Query() query: RelatedWorkItemsBatchQueryDto,
  ): Promise<RelatedWorkItemsBatchResponseDto> {
    const context: JobsLogContext = {
      method: 'getRelatedWorkItemsByIds',
      service: 'WorkItemController',
    };

    this.customLogger.log(
      `[CONTROLLER] Fetching related work items for ${query.workItemIds.length} root work item(s), project: ${query.project ?? 'default'}`,
      context,
    );
    const relatedData = await this.workItemService.getRelatedWorkItemsByIds(
      query.workItemIds,
      query.project ?? '',
    );

    this.customLogger.log(
      `[CONTROLLER] Found ${relatedData.workItems.length} related work items, ${relatedData.commits.length} commits, and ${relatedData.visitedPullRequestIds.length} visited PRs for roots ${relatedData.requestedWorkItemIds.join(', ')}`,
      context,
    );

    const response = new RelatedWorkItemsBatchResponseDto();
    response.success = true;
    response.data = new RelatedWorkItemsBatchDataDto();
    response.data.project = query.project || 'N/A';
    response.data.requestedWorkItemIds = relatedData.requestedWorkItemIds;
    response.data.relatedCount = relatedData.workItems.length;
    response.data.workItems = plainToInstance(
      WorkItemDto,
      relatedData.workItems,
    );
    response.data.visitedPullRequestIds = relatedData.visitedPullRequestIds;
    response.data.commits = plainToInstance(CommitInfo, relatedData.commits);
    response.data.commitCount = relatedData.commits.length;
    return response;
  }

  /**
   * Get a specific work item by ID
   * @param id - The work item ID
   * @returns An object with `success` and `data` containing the work item
   */
  @Get('/:id')
  @ApiOperation({ summary: 'Get work item by ID' })
  @ApiParam({
    description: 'Work item ID',
    name: 'id',
    required: true,
    type: Number,
  })
  @ApiOkResponse({
    description: 'Work item returned',
    type: WorkItemResponseDto,
  })
  @ApiInternalServerErrorResponse({ description: 'Failed to fetch work item' })
  public async getWorkItem(
    @Param('id') id: string,
  ): Promise<WorkItemResponseDto> {
    const context: JobsLogContext = {
      method: 'getWorkItem',
      service: 'WorkItemController',
    };

    const workItemId = Number.parseInt(id, 10);
    this.customLogger.log(
      `[CONTROLLER] Fetching work item ${workItemId}`,
      context,
    );
    const workItem = await this.workItemService.getWorkItemById(workItemId);

    this.customLogger.log(
      `[CONTROLLER] Successfully fetched work item ${workItemId}`,
      context,
    );

    const response = new WorkItemResponseDto();
    response.success = true;
    response.data = plainToInstance(WorkItemDto, workItem);
    return response;
  }

  /**
   * Get related work items recursively (children + PR-linked)
   * @param id - Root work item ID
   * @param project - Optional Azure DevOps project name used for PR expansion
   * @returns An object with `success` and `data` containing related work items
   */
  @Get('/:id/related')
  @ApiOperation({ summary: 'Get related work items by ID' })
  @ApiParam({
    description: 'Root work item ID',
    name: 'id',
    required: true,
    type: Number,
  })
  @ApiQuery({
    description: 'Optional Azure DevOps project name',
    name: 'project',
    required: false,
    type: String,
  })
  @ApiOkResponse({ description: 'Related work items returned' })
  @ApiInternalServerErrorResponse({
    description: 'Failed to fetch related work items',
  })
  public async getRelatedWorkItemsById(
    @Param('id') id: string,
    @Query('project') project?: string,
  ): Promise<RelatedWorkItemsResponseDto> {
    const context: JobsLogContext = {
      method: 'getRelatedWorkItemsById',
      service: 'WorkItemController',
    };

    const workItemId = Number.parseInt(id, 10);
    this.customLogger.log(
      `[CONTROLLER] Fetching related work items for work item ${workItemId}, project: ${project ?? 'default'}`,
      context,
    );
    const relatedData = await this.workItemService.getRelatedWorkItems(
      workItemId,
      project ?? '',
    );

    this.customLogger.log(
      `[CONTROLLER] Found ${relatedData.workItems.length} related work items, ${relatedData.commits.length} commits, and ${relatedData.visitedPullRequestIds.length} visited PRs for ${workItemId}`,
      context,
    );

    const response = new RelatedWorkItemsResponseDto();
    response.success = true;
    response.data = new RelatedWorkItemsDataDto();
    response.data.project = project || 'N/A';
    response.data.relatedCount = relatedData.workItems.length;
    response.data.workItemId = workItemId;
    response.data.workItems = plainToInstance(
      WorkItemDto,
      relatedData.workItems,
    );
    response.data.visitedPullRequestIds = relatedData.visitedPullRequestIds;
    response.data.commits = plainToInstance(CommitInfo, relatedData.commits);
    response.data.commitCount = relatedData.commits.length;
    return response;
  }
}

